type neoRuntime struct {
	mu                       sync.RWMutex
	cfg                      *config.Config
	host                     string
	port                     int
	server                   *http.Server
	store                    *neoActorStore
	started                  bool
	cleanup                  context.CancelFunc
	modelMapper              ModelMapper
	secretSource             SecretSource
	connMu                   sync.Mutex
	connections              map[net.Conn]struct{}
	threadDir                string
	githubClient             *http.Client
	githubAPIBase            string
	githubRawBase            string
	projectIndexMu           sync.Mutex
	projectIndexCache        []any
	projectIndexLoaded       bool
	projectIndexStamp        neoWebLocalFileStamp
	projectHistoryStamp      neoWebLocalFileStamp
	writeLocalSnapshot       func(neoCloudThreadSnapshot, string) error
	asyncLocalSnapshots      bool
	localSnapshotMinInterval time.Duration
	// inferStream overrides the provider inference call used by the local agent
	// and subagent loops. Defaults to inferNeoLocalStream; tests set it to replay
	// a scripted session deterministically without a live provider.
	inferStream func(*neoRuntime, neoInferenceRequest, neoStreamCallback) (neoInferenceResult, error)
}

type neoWebLocalFileStamp struct {
	exists       bool
	size         int64
	modifiedNano int64
}

// subagentInfer runs one inference for a local subagent loop, honoring a test
// override when present.
func (rt *neoRuntime) subagentInfer(request neoInferenceRequest, onDelta neoStreamCallback) (neoInferenceResult, error) {
	if rt != nil && rt.inferStream != nil {
		return rt.inferStream(rt, request, onDelta)
	}
	return inferNeoLocalStream(rt, request, onDelta)
}

func newNeoRuntime(cfg *config.Config) *neoRuntime {
	host, port := neoRuntimeAddress(cfg)
	rt := &neoRuntime{
		cfg:                      cfg,
		host:                     host,
		port:                     port,
		store:                    newNeoActorStore(),
		connections:              map[net.Conn]struct{}{},
		threadDir:                neoAmpThreadStoreDir(),
		localSnapshotMinInterval: neoLocalSnapshotMinInterval,
	}
	rt.store.runtime = rt
	return rt
}

// setModelMapper installs the shared model mapper so Neo inference can honor
// user-configured model_mappings rules (e.g., remap gpt-5.5 -> claude-opus-4-7
// when the codex provider is out of credits).
func (rt *neoRuntime) setModelMapper(mapper ModelMapper) {
	if rt == nil {
		return
	}
	rt.mu.Lock()
	rt.modelMapper = mapper
	rt.mu.Unlock()
}

// getModelMapper returns the configured model mapper, or nil if unset.
func (rt *neoRuntime) getModelMapper() ModelMapper {
	if rt == nil {
		return nil
	}
	rt.mu.RLock()
	defer rt.mu.RUnlock()
	return rt.modelMapper
}

func (rt *neoRuntime) setSecretSource(source SecretSource) {
	if rt == nil {
		return
	}
	rt.mu.Lock()
	rt.secretSource = source
	rt.mu.Unlock()
}

func (rt *neoRuntime) getSecretSource() SecretSource {
	if rt == nil {
		return nil
	}
	rt.mu.RLock()
	defer rt.mu.RUnlock()
	return rt.secretSource
}

func neoRequestContextWithClientAPIKey(r *http.Request) context.Context {
	if r == nil {
		return context.Background()
	}
	ctx := r.Context()
	if key := strings.TrimSpace(r.Header.Get(neoInternalClientAPIKeyHeader)); key != "" {
		ctx = context.WithValue(ctx, clientAPIKeyContextKey{}, key)
	}
	return ctx
}

func neoRuntimeEnabled(cfg *config.Config) bool {
	if cfg == nil {
		return false
	}
	if cfg.AmpCode.NeoLocalRuntime.Enabled == nil {
		return false
	}
	return *cfg.AmpCode.NeoLocalRuntime.Enabled
}

func neoRuntimeAddress(cfg *config.Config) (string, int) {
	host := strings.TrimSpace(cfg.AmpCode.NeoLocalRuntime.Host)
	if host == "" {
		host = defaultNeoRuntimeHost
	}
	port := cfg.AmpCode.NeoLocalRuntime.Port
	if port <= 0 {
		port = defaultNeoRuntimePort
	}
	return host, port
}

func (rt *neoRuntime) start() error {
	if rt == nil {
		return nil
	}
	rt.mu.Lock()
	defer rt.mu.Unlock()
	if rt.started {
		return nil
	}

	addr := net.JoinHostPort(rt.host, fmt.Sprintf("%d", rt.port))
	listener, err := neoRuntimeListenWithRetry("tcp", addr)
	if err != nil {
		return fmt.Errorf("listen on amp neo local runtime %s: %w", addr, err)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/", rt.handleHTTP)
	server := &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 10 * time.Second,
		ConnState:         rt.trackConnectionState,
	}
	rt.server = server
	ctx, cleanup := context.WithCancel(context.Background())
	rt.cleanup = cleanup
	rt.started = true

	go func() {
		log.Infof("amp neo local runtime listening on http://%s", server.Addr)
		if errServe := server.Serve(listener); errServe != nil && !errors.Is(errServe, http.ErrServerClosed) {
			log.Warnf("amp neo local runtime stopped: %v", errServe)
		}
	}()
	go rt.actorPruneLoop(ctx)

	return nil
}

func neoRuntimeListenWithRetry(network, addr string) (net.Listener, error) {
	deadline := time.Now().Add(neoRuntimeBindRetryTimeout)
	var lastErr error
	for {
		listener, err := neoRuntimeListen(network, addr)
		if err == nil {
			return listener, nil
		}
		lastErr = err
		if !neoRuntimeBindRetryable(err) || neoRuntimeBindRetryTimeout <= 0 || !time.Now().Before(deadline) {
			return nil, lastErr
		}
		sleep := neoRuntimeBindRetryInterval
		if sleep <= 0 {
			sleep = 10 * time.Millisecond
		}
		if remaining := time.Until(deadline); remaining < sleep {
			sleep = remaining
		}
		if sleep > 0 {
			time.Sleep(sleep)
		}
	}
}

func neoRuntimeBindRetryable(err error) bool {
	return errors.Is(err, syscall.EADDRINUSE)
}

func (rt *neoRuntime) stop(ctx context.Context) error {
	return rt.stopWithOptions(ctx, neoRuntimeStopOptions{
		stopExecutors:       true,
		closeReason:         "Actor stopped",
		transportClose:      true,
		flushLocalSnapshots: true,
	})
}

func (rt *neoRuntime) shutdown(ctx context.Context) error {
	return rt.stopWithOptions(ctx, neoRuntimeStopOptions{
		stopExecutors:        false,
		transportClose:       true,
		flushLocalSnapshots:  true,
		preserveExecutorWork: true,
	})
}

func (rt *neoRuntime) rebind(ctx context.Context) error {
	return rt.stopWithOptions(ctx, neoRuntimeStopOptions{
		stopExecutors:        true,
		transportClose:       true,
		flushLocalSnapshots:  true,
		preserveExecutorWork: true,
	})
}

type neoRuntimeStopOptions struct {
	stopExecutors        bool
	closeReason          string
	transportClose       bool
	flushLocalSnapshots  bool
	preserveExecutorWork bool
}

func (rt *neoRuntime) stopWithOptions(ctx context.Context, options neoRuntimeStopOptions) error {
	if rt == nil {
		return nil
	}
	rt.mu.Lock()
	defer rt.mu.Unlock()
	if !rt.started || rt.server == nil {
		return nil
	}
	rt.started = false
	if rt.cleanup != nil {
		rt.cleanup()
		rt.cleanup = nil
	}
	server := rt.server
	rt.server = nil
	flushLocalSnapshots := options.flushLocalSnapshots && rt.localThreadSnapshotsEnabledLocked()
	if flushLocalSnapshots && options.preserveExecutorWork {
		rt.store.preserveExecutorWorkOnClose()
	}
	if flushLocalSnapshots && options.stopExecutors {
		rt.store.stopAllSpawnedExecutors(options.preserveExecutorWork)
		if !options.preserveExecutorWork {
			rt.store.disconnectAllExecutors()
		}
	}
	if options.transportClose {
		err := server.Close()
		if errors.Is(err, http.ErrServerClosed) {
			err = nil
		}
		rt.store.closeAllSockets(options.closeReason, true)
		rt.closeTrackedConnections()
		if options.stopExecutors {
			rt.store.stopAllSpawnedExecutors(options.preserveExecutorWork)
			if !options.preserveExecutorWork {
				rt.store.disconnectAllExecutors()
			}
		}
		if flushLocalSnapshots {
			rt.store.syncLocalThreadSnapshots()
		}
		rt.store.closeLocalSnapshotSyncs()
		rt.store.disposeAll(options.stopExecutors, options.closeReason, options.transportClose)
		return err
	}
	err := server.Shutdown(ctx)
	if flushLocalSnapshots {
		rt.store.syncLocalThreadSnapshots()
	}
	rt.store.closeLocalSnapshotSyncs()
	rt.store.disposeAll(options.stopExecutors, options.closeReason, options.transportClose)
	rt.closeTrackedConnections()
	return err
}

func (rt *neoRuntime) trackConnectionState(conn net.Conn, state http.ConnState) {
	if rt == nil || conn == nil {
		return
	}
	switch state {
	case http.StateNew, http.StateActive, http.StateIdle, http.StateHijacked:
		rt.connMu.Lock()
		if rt.connections == nil {
			rt.connections = map[net.Conn]struct{}{}
		}
		rt.connections[conn] = struct{}{}
		rt.connMu.Unlock()
	case http.StateClosed:
		rt.unregisterConnection(conn)
	}
}

func (rt *neoRuntime) unregisterConnection(conn net.Conn) {
	if rt == nil || conn == nil {
		return
	}
	rt.connMu.Lock()
	delete(rt.connections, conn)
	rt.connMu.Unlock()
}

func (rt *neoRuntime) closeTrackedConnections() {
	if rt == nil {
		return
	}
	rt.connMu.Lock()
	connections := make([]net.Conn, 0, len(rt.connections))
	for conn := range rt.connections {
		connections = append(connections, conn)
	}
	rt.connections = map[net.Conn]struct{}{}
	rt.connMu.Unlock()
	for _, conn := range connections {
		if err := conn.Close(); err != nil && !errors.Is(err, net.ErrClosed) {
			log.Debugf("amp neo local runtime connection close failed: %v", err)
		}
	}
}

func (rt *neoRuntime) updateConfig(cfg *config.Config) error {
	if rt == nil || cfg == nil {
		return nil
	}
	rt.mu.Lock()
	rt.cfg = cfg
	rt.mu.Unlock()
	return nil
}

func (rt *neoRuntime) configSnapshot() *config.Config {
	rt.mu.RLock()
	defer rt.mu.RUnlock()
	return rt.cfg
}

func (rt *neoRuntime) localThreadSnapshotsEnabled() bool {
	if rt == nil {
		return false
	}
	rt.mu.RLock()
	defer rt.mu.RUnlock()
	return rt.localThreadSnapshotsEnabledLocked()
}

func (rt *neoRuntime) localThreadSnapshotsEnabledLocked() bool {
	if rt == nil || strings.TrimSpace(rt.threadDir) == "" {
		return false
	}
	return neoRuntimeEnabled(rt.cfg)
}

func (rt *neoRuntime) actorPruneLoop(ctx context.Context) {
	ticker := time.NewTicker(neoActorPruneInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			pruned := rt.store.pruneIdle(time.Now(), neoActorIdleTTL)
			if pruned > 0 {
				log.Debugf("amp neo local runtime pruned %d idle actor(s)", pruned)
			}
		}
	}
}

func (rt *neoRuntime) handleHTTP(w http.ResponseWriter, r *http.Request) {
	if strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		rt.handleWebSocket(w, r)
		return
	}

	switch {
	case r.Method == http.MethodGet && (r.URL.Path == "/metadata" || r.URL.Path == "/actors/metadata"):
		// RivetKit's client performs a mandatory pre-connection metadata lookup to
		// discover the engine endpoint. Newer Amp binaries moved this probe from
		// `/metadata` to `/actors/metadata`; both must return the same engine
		// descriptor or the client's retry-forever lookup never resolves and the
		// thread transport loops on connect_failed.
		writeNeoJSON(w, http.StatusOK, map[string]any{
			"clientEndpoint": neoRuntimeClientEndpoint(r),
			// The RivetKit client only adopts the discovered endpoint/token when
			// clientEndpoint is present, then attaches clientToken (as rvt-token) to
			// every subsequent actor request. Returning a token here is what lets the
			// thread WebSocket pass the engine auth gate; the proxy strips it before it
			// reaches the bridge, which resolves actors by rvt-key.
			"clientNamespace": neoMetadataRequestNamespace(r),
			"clientToken":     neoLocalRuntimeClientToken,
			"runtime":         "engine",
			"version":         "2.3.0-rc.4",
			"git_sha":         "local-cliproxyapi",
			"build_timestamp": "2026-05-07T00:00:00Z",
			"rustc_version":   "local",
			"rustc_host":      runtimeHost(),
			"cargo_target":    runtimeArch(),
			"cargo_profile":   "release",
		})
	case r.URL.Path == "/actors" && r.Method == http.MethodGet:
		writeNeoJSON(w, http.StatusOK, map[string]any{"actors": rt.store.findActors(r.URL.Query())})
	case r.URL.Path == "/actors" && (r.Method == http.MethodPut || r.Method == http.MethodPost):
		body := readNeoJSON(r.Body)
		stored, created := rt.store.upsert(body, r.Method == http.MethodPut)
		writeNeoJSON(w, http.StatusOK, map[string]any{"actor": stored.record, "created": created})
	case isNeoThreadImportPath(r.URL.Path) && r.Method == http.MethodPost:
		rt.handleThreadImport(w, r)
	case isNeoContextAnalysisRequestPath(r.URL.Path) && r.Method == http.MethodGet:
		rt.handleContextAnalysisRequest(w, r)
	case isNeoDynamicReloadPath(r.URL.Path) && r.Method == http.MethodPut:
		writeNeoJSON(w, http.StatusOK, map[string]any{"ok": true})
	case isNeoStateRequestPath(r.URL.Path) && r.Method == http.MethodGet:
		rt.handleStateRequest(w, r)
	case isNeoMessagesRequestPath(r.URL.Path) && r.Method == http.MethodGet:
		rt.handleMessagesRequest(w, r)
	case neoGatewayActionRequest(r):
		rt.handleGatewayActionRequest(w, r)
	case rt.serveActorKVKeyHTTP(w, r):
		return
	case isNeoSkillsPath(r.URL.Path) && (r.Method == http.MethodGet || r.Method == http.MethodPost):
		log.Debugf("amp neo local runtime HTTP skills method=%s path=%s rawQuery=%s", r.Method, r.URL.Path, r.URL.RawQuery)
		writeNeoJSON(w, http.StatusOK, rt.store.skillsResponse(neoActorIDFromSkillsPath(r.URL.Path), r.URL.Query()))
	case strings.HasPrefix(r.URL.Path, "/actors/") && r.Method == http.MethodDelete:
		rt.store.delete(strings.TrimPrefix(r.URL.Path, "/actors/"))
		w.WriteHeader(http.StatusNoContent)
	default:
		log.Debugf("amp neo local runtime HTTP not_found method=%s path=%s rawQuery=%s", r.Method, r.URL.Path, r.URL.RawQuery)
		writeNeoJSON(w, http.StatusNotFound, map[string]any{"error": "not_found"})
	}
}

func neoGatewayActionName(path string) string {
	path = neoStripActorsRivetPrefix("/" + strings.Trim(path, "/"))
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) != 4 || parts[0] != "gateway" || parts[2] != "action" {
		return ""
	}
	return strings.TrimSpace(parts[3])
}

func neoGatewayActionRequest(r *http.Request) bool {
	return r != nil && r.Method == http.MethodPost && r.URL != nil && neoGatewayActionName(r.URL.Path) != ""
}

func decodeNeoGatewayActionArgs(r *http.Request) ([]any, uint16, error) {
	if r == nil || r.Body == nil {
		return nil, 0, errors.New("missing action body")
	}
	raw, err := io.ReadAll(r.Body)
	if err != nil {
		return nil, 0, err
	}
	if strings.Contains(strings.ToLower(r.Header.Get("Content-Type")), "json") || strings.EqualFold(r.Header.Get("x-rivet-encoding"), "json") {
		var payload map[string]any
		if err := json.Unmarshal(raw, &payload); err != nil {
			return nil, 0, err
		}
		return arrayValue(payload["args"]), 0, nil
	}
	if len(raw) < 3 {
		return nil, 0, io.ErrUnexpectedEOF
	}
	version := binary.LittleEndian.Uint16(raw[:2])
	offset := 2
	encoded, err := neoRivetBareReadBytes(raw, &offset)
	if err != nil {
		return nil, 0, err
	}
	decoded, err := neoRivetDecodeData(encoded)
	if err != nil {
		return nil, 0, err
	}
	return arrayValue(decoded), version, nil
}

func writeNeoGatewayActionResult(w http.ResponseWriter, result any, version uint16) {
	if version == 0 {
		writeNeoJSON(w, http.StatusOK, map[string]any{"output": result})
		return
	}
	encoded, err := neoRivetEncodeData(result)
	if err != nil {
		writeNeoJSON(w, http.StatusInternalServerError, map[string]any{"error": "action_encode_failed"})
		return
	}
	var body bytes.Buffer
	neoRivetBareWriteBytes(&body, encoded)
	payload := make([]byte, 2+body.Len())
	binary.LittleEndian.PutUint16(payload[:2], version)
	copy(payload[2:], body.Bytes())
	w.Header().Set("Content-Type", "application/octet-stream")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(payload)
}

func (rt *neoRuntime) handleGatewayActionRequest(w http.ResponseWriter, r *http.Request) {
	actor := rt.store.actorForGatewayRequest(r)
	if actor == nil {
		writeNeoJSON(w, http.StatusNotFound, map[string]any{"error": "actor_not_found"})
		return
	}
	args, version, err := decodeNeoGatewayActionArgs(r)
	if err != nil {
		writeNeoJSON(w, http.StatusBadRequest, map[string]any{"error": "invalid_action_body"})
		return
	}
	result := actor.handleForSocket(&neoSocket{runnerID: stringValue(neoRivetConnectionParams(r, nil)["runnerId"])}, map[string]any{
		"type": neoGatewayActionName(r.URL.Path),
		"args": args,
	})
	writeNeoGatewayActionResult(w, result, version)
}

func (rt *neoRuntime) serveActorKVKeyHTTP(w http.ResponseWriter, r *http.Request) bool {
	if rt == nil || r == nil || r.URL == nil {
		return false
	}
	actorID, key, ok := neoActorKVKeyPath(r.URL.EscapedPath())
	if !ok {
		return false
	}
	actor := rt.store.get(actorID)
	switch r.Method {
	case http.MethodGet:
		var value any
		if actor != nil {
			actor.touch()
			value, _ = actor.kvGet(key)
		}
		log.Debugf("amp neo local runtime actor kv get actor=%s key=%s hit=%v", actorID, key, actor != nil)
		writeNeoJSON(w, http.StatusOK, map[string]any{"value": value})
		return true
	case http.MethodPut, http.MethodPost:
		if actor == nil {
			writeNeoJSON(w, http.StatusNotFound, map[string]any{"error": "actor_not_found"})
			return true
		}
		actor.touch()
		value := readNeoKVValue(r.Body)
		actor.kvSet(key, value)
		writeNeoJSON(w, http.StatusOK, map[string]any{"ok": true, "value": value})
		return true
	case http.MethodDelete:
		if actor != nil {
			actor.touch()
			actor.kvDelete(key)
		}
		writeNeoJSON(w, http.StatusOK, map[string]any{"ok": true})
		return true
	default:
		writeNeoJSON(w, http.StatusMethodNotAllowed, map[string]any{"error": "method_not_allowed"})
		return true
	}
}

func readNeoKVValue(r io.Reader) any {
	var payload any
	if err := json.NewDecoder(r).Decode(&payload); err != nil {
		return nil
	}
	if m, ok := payload.(map[string]any); ok {
		if value, exists := m["value"]; exists {
			return value
		}
	}
	return payload
}

func (a *neoActor) kvGet(key string) (any, bool) {
	if a == nil {
		return nil, false
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	value, ok := a.kv[key]
	return value, ok
}

func (a *neoActor) kvSet(key string, value any) {
	if a == nil || key == "" {
		return
	}
	a.mu.Lock()
	if a.kv == nil {
		a.kv = map[string]any{}
	}
	a.kv[key] = value
	a.mu.Unlock()
	a.syncCloudAsync()
}

func (a *neoActor) kvDelete(key string) {
	if a == nil || key == "" {
		return
	}
	a.mu.Lock()
	_, existed := a.kv[key]
	delete(a.kv, key)
	a.mu.Unlock()
	if existed {
		a.syncCloudAsync()
	}
}

func neoActorKVKeyPath(path string) (string, string, bool) {
	path = "/" + strings.Trim(path, "/")
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) != 5 || parts[0] != "actors" || parts[2] != "kv" || parts[3] != "keys" {
		return "", "", false
	}
	actorID := neoActorPathID(parts[1])
	key, err := url.PathUnescape(parts[4])
	if err != nil {
		key = parts[4]
	}
	return actorID, key, actorID != ""
}

func (rt *neoRuntime) handleThreadImport(w http.ResponseWriter, r *http.Request) {
	body := readNeoJSON(r.Body)
	thread := mapValue(body["thread"])
	if len(thread) == 0 {
		writeNeoJSON(w, http.StatusBadRequest, map[string]any{"error": "missing_thread"})
		return
	}
	threadID := firstNonEmptyString(thread["id"], findThreadID(thread))
	if !neoThreadIDExactPattern.MatchString(threadID) {
		writeNeoJSON(w, http.StatusBadRequest, map[string]any{"error": "invalid_thread_id"})
		return
	}

	actor := rt.store.actorForGatewayRequest(r)
	if actor == nil {
		actor = rt.store.ensureThreadActor(threadID)
	}
	actor.touch()
	if err := actor.importThreadLocalOnly(thread); err != nil {
		log.Warnf("amp neo local runtime thread import failed thread=%s: %v", threadID, err)
		writeNeoJSON(w, http.StatusBadRequest, map[string]any{"error": "import_failed", "message": err.Error()})
		return
	}
	writeNeoJSON(w, http.StatusOK, map[string]any{"ok": true, "threadId": threadID})
}

// handleContextAnalysisRequest serves the Amp CLI's `thread: analyze context`
// command. The binary calls threadActor.fetch("/context-analysis"), which the
// Rivet gateway exposes to us as /gateway/threadActor/request/context-analysis.
func (rt *neoRuntime) handleContextAnalysisRequest(w http.ResponseWriter, r *http.Request) {
	actor := rt.contextAnalysisActorForRequest(r)
	if actor == nil {
		writeNeoJSON(w, http.StatusNotFound, map[string]any{"ok": false, "error": "actor_not_found"})
		return
	}
	actor.touch()
	writeNeoJSON(w, http.StatusOK, map[string]any{"ok": true, "analysis": actor.contextAnalysisResponse()})
}

func (rt *neoRuntime) contextAnalysisActorForRequest(r *http.Request) *neoActor {
	if rt == nil || rt.store == nil || r == nil || r.URL == nil {
		return nil
	}
	if actor := rt.store.actorForGatewayRequest(r); actor != nil {
		return actor
	}
	return nil
}

// handleStateRequest serves a JSON snapshot of the actor state similar to
// what would be sent over the WebSocket on resume. Some clients (notably the
// IDE side panel) fetch state without subscribing to live updates.
func (rt *neoRuntime) handleStateRequest(w http.ResponseWriter, r *http.Request) {
	actor := rt.store.actorForGatewayRequest(r)
	if actor == nil {
		writeNeoJSON(w, http.StatusNotFound, map[string]any{"error": "actor_not_found"})
		return
	}
	actor.touch()
	writeNeoJSON(w, http.StatusOK, actor.stateSnapshotResponse())
}

// handleMessagesRequest returns the message history with simple offset/limit
// pagination so clients can fetch large histories without loading the full
// snapshot over the WebSocket.
func (rt *neoRuntime) handleMessagesRequest(w http.ResponseWriter, r *http.Request) {
	actor := rt.store.actorForGatewayRequest(r)
	if actor == nil {
		writeNeoJSON(w, http.StatusNotFound, map[string]any{"error": "actor_not_found"})
		return
	}
	actor.touch()
	q := r.URL.Query()
	limit, _ := strconv.Atoi(q.Get("limit"))
	if limit <= 0 || limit > 1000 {
		limit = 200
	}
	offset, _ := strconv.Atoi(q.Get("offset"))
	if offset < 0 {
		offset = 0
	}
	writeNeoJSON(w, http.StatusOK, actor.messagesResponse(offset, limit))
}

func isNeoThreadImportPath(path string) bool {
	path = "/" + strings.Trim(path, "/")
	return path == "/request/import" || strings.HasSuffix(path, "/request/import")
}

func isNeoContextAnalysisRequestPath(path string) bool {
	path = "/" + strings.Trim(path, "/")
	return path == "/request/context-analysis" || strings.HasSuffix(path, "/request/context-analysis")
}

func isNeoDynamicReloadPath(path string) bool {
	path = "/" + strings.Trim(path, "/")
	return path == "/dynamic/reload" || strings.HasSuffix(path, "/dynamic/reload")
}

func isNeoStateRequestPath(path string) bool {
	path = "/" + strings.Trim(path, "/")
	return path == "/request/state" || strings.HasSuffix(path, "/request/state")
}

func isNeoMessagesRequestPath(path string) bool {
	path = "/" + strings.Trim(path, "/")
	return path == "/request/messages" || strings.HasSuffix(path, "/request/messages")
}

func neoSkipReadyWaitRequested(r *http.Request, protocols []string) bool {
	for _, protocol := range protocols {
		if strings.EqualFold(strings.TrimSpace(protocol), "rivet_skip_ready_wait") {
			return true
		}
	}
	if r == nil || r.URL == nil {
		return false
	}
	value := strings.TrimSpace(r.URL.Query().Get("rvt-skip-ready-wait"))
	return value == "1" || strings.EqualFold(value, "true")
}

func neoJSONRPCTransportRequested(r *http.Request, protocols []string) bool {
	values := append([]string{}, protocols...)
	for _, protocol := range protocols {
		if !strings.HasPrefix(protocol, "rivet_conn_params.") {
			continue
		}
		encoded := strings.TrimPrefix(protocol, "rivet_conn_params.")
		decoded, err := url.QueryUnescape(encoded)
		if err != nil {
			continue
		}
		values = append(values, decoded)
		var params any
		if err := json.Unmarshal([]byte(decoded), &params); err == nil && neoValueContainsJSONRPCTransport(params) {
			return true
		}
	}
	if r != nil {
		if r.URL != nil {
			query := r.URL.Query()
			values = append(values, r.URL.RawQuery, query.Get("transport"), query.Get("rvt-transport"))
			if neoValueContainsJSONRPCTransport(decodeNeoGatewayInput(query.Get("rvt-input"))) {
				return true
			}
		}
		values = append(values, r.Header.Get("Sec-WebSocket-Protocol"), r.Header.Get("x-rivet-conn-params"))
	}
	for _, value := range values {
		if strings.Contains(strings.ToLower(value), "json-rpc") {
			return true
		}
	}
	return false
}

func neoRivetConnectionParams(r *http.Request, protocols []string) map[string]any {
	values := make([]string, 0, len(protocols)+1)
	if r != nil {
		values = append(values, r.Header.Get("x-rivet-conn-params"))
	}
	for _, protocol := range protocols {
		if strings.HasPrefix(protocol, "rivet_conn_params.") {
			values = append(values, strings.TrimPrefix(protocol, "rivet_conn_params."))
		}
	}
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if decoded, err := url.QueryUnescape(value); err == nil {
			value = decoded
		}
		var params map[string]any
		if json.Unmarshal([]byte(value), &params) == nil && len(params) > 0 {
			return params
		}
	}
	return nil
}

func neoValueContainsJSONRPCTransport(value any) bool {
	switch typed := value.(type) {
	case map[string]any:
		for key, item := range typed {
			if strings.EqualFold(key, "transport") || strings.EqualFold(key, "threadActorTransport") {
				if strings.EqualFold(stringValue(item), "json-rpc") {
					return true
				}
			}
			if neoValueContainsJSONRPCTransport(item) {
				return true
			}
		}
	case []any:
		for _, item := range typed {
			if neoValueContainsJSONRPCTransport(item) {
				return true
			}
		}
	case string:
		return strings.EqualFold(typed, "json-rpc")
	}
	return false
}

func runtimeHost() string {
	return runtime.GOOS
}

func runtimeArch() string {
	return runtime.GOARCH
}

func neoRuntimeClientEndpoint(r *http.Request) string {
	scheme := "http"
	host := "127.0.0.1"
	if r != nil {
		if forwardedHost := strings.TrimSpace(r.Header.Get("X-Forwarded-Host")); forwardedHost != "" {
			host = strings.TrimSpace(strings.Split(forwardedHost, ",")[0])
		} else if strings.TrimSpace(r.Host) != "" {
			host = strings.TrimSpace(r.Host)
		}
		if forwarded := strings.TrimSpace(r.Header.Get("X-Forwarded-Proto")); forwarded != "" && !neoRequestHostIsLoopback(host) {
			scheme = strings.TrimSpace(strings.Split(forwarded, ",")[0])
		} else if r.TLS != nil {
			scheme = "https"
		}
	}
	if scheme == "" {
		scheme = "http"
	}
	if host == "" {
		host = "127.0.0.1"
	}
	return scheme + "://" + host
}

func neoRequestHostIsLoopback(host string) bool {
	host = strings.TrimSpace(host)
	if host == "" {
		return false
	}
	if parsedHost, _, err := net.SplitHostPort(host); err == nil {
		host = parsedHost
	}
	host = strings.Trim(host, "[]")
	return strings.EqualFold(host, "localhost") || host == "127.0.0.1" || host == "::1"
}

func isNeoSkillsPath(path string) bool {
	path = "/" + strings.Trim(strings.TrimSuffix(path, "/"), "/")
	if path == "/skills" || path == "/request/skills" || path == "/request/list-skills" {
		return true
	}
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 3 && parts[0] == "actors" && parts[2] == "skills" && parts[1] != "" {
		return true
	}
	return len(parts) >= 3 && parts[len(parts)-2] == "request" && (parts[len(parts)-1] == "skills" || parts[len(parts)-1] == "list-skills")
}

func neoActorIDFromSkillsPath(path string) string {
	path = strings.Trim(path, "/")
	parts := strings.Split(path, "/")
	for i, part := range parts {
		if (part == "actors" || part == "gateway") && i+1 < len(parts) {
			return neoActorPathID(parts[i+1])
		}
	}
	for i := len(parts) - 1; i >= 0; i-- {
		if parts[i] != "" && parts[i] != "actors" && parts[i] != "gateway" && parts[i] != "request" && parts[i] != "skills" && parts[i] != "list-skills" {
			return neoActorPathID(parts[i])
		}
	}
	return ""
}

func neoActorPathID(segment string) string {
	segment, _, _ = strings.Cut(segment, "@")
	if unescaped, err := url.PathUnescape(segment); err == nil {
		return unescaped
	}
	return segment
}

func (rt *neoRuntime) handleWebSocket(w http.ResponseWriter, r *http.Request) {
	protocols := parseWebSocketProtocols(r.Header.Get("Sec-WebSocket-Protocol"))
	actorID := extractNeoActorID(protocols)
	if actorID == "" {
		actorID = firstNonEmptyString(r.URL.Query().Get("actorId"), r.Header.Get("x-rivet-actor"))
	}
	actor := rt.store.get(actorID)
	if actor == nil {
		actor = rt.store.actorForGatewayRequest(r)
		if actor == nil {
			http.Error(w, "Unknown local Neo actor", http.StatusNotFound)
			return
		}
	}

	responseHeader := http.Header{}
	if selected := selectNeoSubprotocol(protocols); selected != "" {
		responseHeader.Set("Sec-WebSocket-Protocol", selected)
	}
	upgrader := websocket.Upgrader{
		CheckOrigin:       func(*http.Request) bool { return true },
		EnableCompression: true,
		ReadBufferSize:    32 * 1024,
		WriteBufferSize:   32 * 1024,
	}
	conn, err := upgrader.Upgrade(w, r, responseHeader)
	if err != nil {
		log.Warnf("amp neo websocket upgrade failed: %v", err)
		return
	}
	rivetAction := neoRivetActionProtocolRequested(r, protocols, actor)
	rivetBare := rivetAction && neoRivetBareRequested(protocols)
	webLocalInferenceSocket := neoWebLocalInferenceSocketRequested(r, actor)
	conn.SetReadLimit(neoWSReadLimit)
	conn.EnableWriteCompression(true)
	conn.SetPingHandler(func(data string) error {
		_ = conn.WriteControl(websocket.PongMessage, []byte(data), time.Time{})
		return nil
	})
	socket := &neoSocket{
		conn:             conn,
		jsonRPC:          neoJSONRPCTransportRequested(r, protocols),
		rivetAction:      rivetAction,
		rivetBare:        rivetBare,
		rivetConnection:  "conn-" + randomBase62(22),
		localExtensions:  neoLocalRuntimeExtensionsRequested(r),
		webLocalObserver: webLocalInferenceSocket,
		clientAPIKey:     strings.TrimSpace(r.Header.Get(neoInternalClientAPIKeyHeader)),
		runnerID:         stringValue(neoRivetConnectionParams(r, protocols)["runnerId"]),
	}
	if underlying := conn.UnderlyingConn(); underlying != nil {
		defer rt.unregisterConnection(underlying)
	}
	if rivetAction {
		socket.sendRivetInit(actor.id)
	}
	actor.open(socket, !rivetAction && !neoSkipReadyWaitRequested(r, protocols))
	neoApplyWebLocalInferenceBootstrapQuery(r, actor)
	if neoWebLocalInferenceBootstrapExecutorRequested(r, actor) && actor.webLocalInferenceBootstrapNeeded() {
		actor.spawnExecutor(map[string]any{
			"type":                    "client_spawn_executor",
			"requestId":               "web-local-inference-" + randomBase62(12),
			"replaceExistingExecutor": false,
		})
	}
	if webLocalInferenceSocket {
		actor.sendCurrentExecutorState(socket)
	}
	defer actor.close(socket)
	defer conn.Close()

	for {
		messageType, payload, err := conn.ReadMessage()
		if err != nil {
			if websocket.IsUnexpectedCloseError(err, websocket.CloseNormalClosure, websocket.CloseGoingAway) {
				log.Debugf("amp neo websocket read error: %v", err)
			}
			return
		}
		if messageType != websocket.TextMessage && messageType != websocket.BinaryMessage {
			continue
		}
		if len(payload) == 0 {
			continue
		}
		// text-mode keepalive used by older clients.
		if messageType == websocket.TextMessage && string(payload) == "ping" {
			socket.sendText("pong")
			continue
		}
		messages, err := decodeNeoClientFrame(payload)
		if err != nil {
			socket.send(map[string]any{"type": "error", "message": "Invalid Neo protocol message", "code": "PARSE_ERROR"})
			continue
		}
		for _, msg := range messages {
			jsonRPCFrame := boolValue(msg[neoJSONRPCFrameKey])
			requestID, hasRequestID := msg[neoJSONRPCRequestIDKey]
			rivetActionFrame := boolValue(msg[neoRivetActionFrameKey])
			rivetActionRequestID, hasRivetActionRequestID := msg[neoRivetActionRequestIDKey]
			rivetBareFrame := boolValue(msg[neoRivetBareFrameKey])
			delete(msg, neoJSONRPCFrameKey)
			delete(msg, neoJSONRPCRequestIDKey)
			delete(msg, neoRivetActionFrameKey)
			delete(msg, neoRivetActionRequestIDKey)
			delete(msg, neoRivetBareFrameKey)
			if jsonRPCFrame {
				socket.setJSONRPC(true)
			}
			if rivetActionFrame {
				socket.setRivetAction(true)
			}
			if rivetBareFrame {
				socket.setRivetBare(true)
			}
			neoInboundMessageHookMu.RLock()
			hook := neoInboundMessageHook
			neoInboundMessageHookMu.RUnlock()
			if hook != nil {
				hook(actor, cloneMap(msg))
			}
			result := actor.handleForSocket(socket, msg)
			if hasRivetActionRequestID {
				socket.sendRivetActionResponse(rivetActionRequestID, result)
			} else if hasRequestID {
				socket.sendJSONRPCResponse(requestID, result)
			}
		}
	}
}

func decodeNeoClientFrame(payload []byte) ([]map[string]any, error) {
	if messages, handled, err := decodeNeoRivetBareClientFrame(payload); handled {
		return messages, err
	}
	var decoded any
	if err := json.Unmarshal(payload, &decoded); err != nil {
		return nil, err
	}
	if msg, ok := decoded.(map[string]any); ok {
		if converted, handled := decodeNeoJSONRPCFrame(msg); handled {
			if converted == nil {
				return nil, nil
			}
			return []map[string]any{converted}, nil
		}
		if converted, handled := decodeNeoRivetActionFrame(msg); handled {
			if converted == nil {
				return nil, nil
			}
			return []map[string]any{converted}, nil
		}
		return []map[string]any{msg}, nil
	}
	items, ok := decoded.([]any)
	if !ok {
		return nil, fmt.Errorf("invalid Neo protocol frame")
	}
	messages := make([]map[string]any, 0, len(items))
	for _, item := range items {
		msg, ok := item.(map[string]any)
		if !ok {
			return nil, fmt.Errorf("invalid Neo protocol batch item")
		}
		if converted, handled := decodeNeoJSONRPCFrame(msg); handled {
			if converted != nil {
				messages = append(messages, converted)
			}
			continue
		}
		if converted, handled := decodeNeoRivetActionFrame(msg); handled {
			if converted != nil {
				messages = append(messages, converted)
			}
			continue
		}
		messages = append(messages, msg)
	}
	return messages, nil
}

func decodeNeoRivetBareClientFrame(payload []byte) ([]map[string]any, bool, error) {
	if len(payload) < 3 || binary.LittleEndian.Uint16(payload[:2]) != neoRivetBareVersion {
		return nil, false, nil
	}
	offset := 2
	tag := payload[offset]
	offset++
	switch tag {
	case 0:
		requestID, err := neoRivetBareReadVarUint(payload, &offset)
		if err != nil {
			return nil, true, err
		}
		name, err := neoRivetBareReadString(payload, &offset)
		if err != nil {
			return nil, true, err
		}
		argBytes, err := neoRivetBareReadBytes(payload, &offset)
		if err != nil {
			return nil, true, err
		}
		args, err := neoRivetDecodeData(argBytes)
		if err != nil {
			return nil, true, err
		}
		msg := map[string]any{"type": name, neoRivetActionFrameKey: true, neoRivetBareFrameKey: true, neoRivetActionRequestIDKey: requestID}
		if array := arrayValue(args); array != nil {
			msg["args"] = array
		}
		return []map[string]any{msg}, true, nil
	case 1:
		if _, err := neoRivetBareReadString(payload, &offset); err != nil {
			return nil, true, err
		}
		if offset >= len(payload) {
			return nil, true, io.ErrUnexpectedEOF
		}
		return nil, true, nil
	default:
		return nil, true, fmt.Errorf("unknown Rivet bare client tag %d", tag)
	}
}

func decodeNeoJSONRPCFrame(frame map[string]any) (map[string]any, bool) {
	method := stringValue(frame["method"])
	if method == "" {
		if frame["jsonrpc"] != nil {
			return nil, true
		}
		return nil, false
	}
	params := mapValue(frame["params"])
	msg := cloneMap(params)
	msg["type"] = method
	msg[neoJSONRPCFrameKey] = true
	if requestID, ok := frame["id"]; ok {
		msg[neoJSONRPCRequestIDKey] = requestID
	}
	return msg, true
}

func decodeNeoRivetActionFrame(frame map[string]any) (map[string]any, bool) {
	body := mapValue(frame["body"])
	if len(body) == 0 {
		return nil, false
	}
	tag := stringValue(body["tag"])
	val := mapValue(body["val"])
	switch tag {
	case "ActionRequest":
		name := stringValue(val["name"])
		if name == "" {
			return nil, true
		}
		msg := map[string]any{"type": name, neoRivetActionFrameKey: true}
		if args := arrayValue(val["args"]); args != nil {
			msg["args"] = args
		}
		if requestID, ok := val["id"]; ok {
			msg[neoRivetActionRequestIDKey] = requestID
		}
		return msg, true
	case "SubscriptionRequest":
		return nil, true
	default:
		return nil, false
	}
}

func neoRivetActionProtocolRequested(r *http.Request, protocols []string, actor *neoActor) bool {
	if actor == nil {
		return false
	}
	if neoJSONRPCTransportRequested(r, protocols) {
		return false
	}
	if neoGatewayUserActorTarget(actor.name) {
		return true
	}
	return neoGatewayThreadActorTarget(actor.name) && neoRivetProtocolRequested(protocols) && neoWebLocalInferenceSocketRequested(r, actor)
}

func neoRivetProtocolRequested(protocols []string) bool {
	for _, protocol := range protocols {
		value := strings.ToLower(strings.TrimSpace(protocol))
		if value == "rivet" || strings.HasPrefix(value, "rivet_") {
			return true
		}
	}
	return false
}

func neoRivetBareRequested(protocols []string) bool {
	for _, protocol := range protocols {
		value := strings.ToLower(strings.TrimSpace(protocol))
		if value == "rivet_encoding.4" || value == "rivet_encoding.bare" {
			return true
		}
	}
	return false
}

func neoRivetEncodeInitFrame(actorID string, connectionID string) []byte {
	var body bytes.Buffer
	body.WriteByte(0)
	neoRivetBareWriteString(&body, actorID)
	neoRivetBareWriteString(&body, connectionID)
	return neoRivetBareVersioned(body.Bytes())
}

func neoRivetEncodeActionResponseFrame(id uint64, result any) ([]byte, error) {
	encoded, err := neoRivetEncodeData(result)
	if err != nil {
		return nil, err
	}
	var body bytes.Buffer
	body.WriteByte(2)
	neoRivetBareWriteVarUint(&body, id)
	neoRivetBareWriteBytes(&body, encoded)
	return neoRivetBareVersioned(body.Bytes()), nil
}

func neoRivetEncodeEventFrame(name string, args any) ([]byte, error) {
	encoded, err := neoRivetEncodeData(args)
	if err != nil {
		return nil, err
	}
	var body bytes.Buffer
	body.WriteByte(3)
	neoRivetBareWriteString(&body, name)
	neoRivetBareWriteBytes(&body, encoded)
	return neoRivetBareVersioned(body.Bytes()), nil
}

func neoRivetBareVersioned(body []byte) []byte {
	out := make([]byte, 2+len(body))
	binary.LittleEndian.PutUint16(out[:2], neoRivetBareVersion)
	copy(out[2:], body)
	return out
}

func neoRivetBareWriteString(buf *bytes.Buffer, value string) {
	neoRivetBareWriteBytes(buf, []byte(value))
}

func neoRivetBareWriteBytes(buf *bytes.Buffer, value []byte) {
	neoRivetBareWriteVarUint(buf, uint64(len(value)))
	buf.Write(value)
}

func neoRivetBareWriteVarUint(buf *bytes.Buffer, value uint64) {
	for value >= 0x80 {
		buf.WriteByte(byte(value) | 0x80)
		value >>= 7
	}
	buf.WriteByte(byte(value))
}

func neoRivetBareReadString(payload []byte, offset *int) (string, error) {
	value, err := neoRivetBareReadBytes(payload, offset)
	if err != nil {
		return "", err
	}
	return string(value), nil
}

func neoRivetBareReadBytes(payload []byte, offset *int) ([]byte, error) {
	length, err := neoRivetBareReadVarUint(payload, offset)
	if err != nil {
		return nil, err
	}
	if length > uint64(len(payload)-*offset) {
		return nil, io.ErrUnexpectedEOF
	}
	value := payload[*offset : *offset+int(length)]
	*offset += int(length)
	return value, nil
}

func neoRivetBareReadVarUint(payload []byte, offset *int) (uint64, error) {
	var value uint64
	var shift uint
	for i := 0; i < 10; i++ {
		if *offset >= len(payload) {
			return 0, io.ErrUnexpectedEOF
		}
		b := payload[*offset]
		*offset = *offset + 1
		value |= uint64(b&0x7f) << shift
		if b < 0x80 {
			return value, nil
		}
		shift += 7
	}
	return 0, fmt.Errorf("Rivet bare varint overflow")
}

func neoRivetEncodeData(value any) ([]byte, error) {
	var out []byte
	err := ugorjicodec.NewEncoderBytes(&out, neoRivetDataHandle).Encode(value)
	return out, err
}

func neoRivetDecodeData(data []byte) (any, error) {
	if len(data) == 0 {
		return nil, nil
	}
	var out any
	if err := ugorjicodec.NewDecoderBytes(data, neoRivetDataHandle).Decode(&out); err != nil {
		return nil, err
	}
	return neoRivetNormalizeData(out), nil
}

func neoRivetNormalizeData(value any) any {
	switch typed := value.(type) {
	case map[string]any:
		out := make(map[string]any, len(typed))
		for key, item := range typed {
			out[key] = neoRivetNormalizeData(item)
		}
		return out
	case map[any]any:
		out := make(map[string]any, len(typed))
		for key, item := range typed {
			out[fmt.Sprint(key)] = neoRivetNormalizeData(item)
		}
		return out
	case []any:
		out := make([]any, len(typed))
		for i, item := range typed {
			out[i] = neoRivetNormalizeData(item)
		}
		return out
	default:
		return value
	}
}

type neoActorStore struct {
	mu        sync.RWMutex
	runtime   *neoRuntime
	actors    map[string]*neoActor
	byNameKey map[string]string
	recent    map[string]neoRecentThreadStatus
}

func newNeoActorStore() *neoActorStore {
	return &neoActorStore{
		actors:    make(map[string]*neoActor),
		byNameKey: make(map[string]string),
		recent:    make(map[string]neoRecentThreadStatus),
	}
}

type neoRecentThreadStatus struct {
	status    map[string]any
	updatedMs int
}

func (s *neoActorStore) get(id string) *neoActor {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.actors[id]
}

func (s *neoActorStore) shouldForceLocalThreadActors() bool {
	if s == nil || s.runtime == nil {
		return false
	}
	cfg := s.runtime.configSnapshot()
	return cfg != nil && neoRuntimeEnabled(cfg) && cfg.AmpCode.NeoLocalRuntime.ForceThreadActors
}

func (s *neoActorStore) actorForGatewayRequest(r *http.Request) *neoActor {
	if s == nil || r == nil || r.URL == nil {
		return nil
	}
	q := r.URL.Query()
	target := neoGatewayTargetFromPath(neoStripActorsRivetPrefix("/" + strings.Trim(r.URL.Path, "/")))
	canonicalTarget := neoCanonicalActorName(target)
	key := strings.TrimSpace(q.Get("rvt-key"))
	requestedThreadID := neoThreadIDFromBridgeRequest(r)

	s.mu.RLock()
	if target != "" {
		if actor := s.actors[target]; actor != nil {
			s.mu.RUnlock()
			return s.gatewayThreadActorWithCloudState(r, actor, target, key)
		}
	}
	if key != "" {
		if id := s.byNameKey[canonicalTarget+"\x00"+key]; id != "" {
			if actor := s.actors[id]; actor != nil {
				s.mu.RUnlock()
				return s.gatewayThreadActorWithCloudState(r, actor, target, key)
			}
		}
		for _, actor := range s.actors {
			if actor.key == key || actor.threadID == key {
				s.mu.RUnlock()
				return s.gatewayThreadActorWithCloudState(r, actor, target, key)
			}
		}
	}
	s.mu.RUnlock()

	method := strings.TrimSpace(q.Get("rvt-method"))
	if (strings.EqualFold(method, "get") || strings.EqualFold(method, "getOrCreate")) && neoGatewayThreadActorTarget(target) {
		if threadID := requestedThreadID; threadID != "" {
			if s.runtime != nil && s.runtime.tryImportNeoCloudLocalThreadActor(neoRequestContextWithClientAPIKey(r), threadID) {
				return s.lookupThreadActor(threadID)
			}
			if s.shouldForceLocalThreadActors() {
				return s.ensureThreadActor(threadID)
			}
			if strings.EqualFold(method, "get") && s.shouldBootstrapThreadActorForGatewayGet(r, threadID) {
				return s.ensureThreadActor(threadID)
			}
		}
	}
	if strings.EqualFold(method, "get") && neoGatewayUserActorTarget(target) && key != "" {
		actor, _ := s.upsert(map[string]any{"name": canonicalTarget, "key": key}, true)
		return actor
	}
	if !strings.EqualFold(method, "getOrCreate") || target == "" || key == "" {
		return nil
	}
	body := map[string]any{"name": canonicalTarget, "key": key}
	if input := decodeNeoGatewayInput(q.Get("rvt-input")); input != nil {
		body["input"] = input
	} else if threadID := requestedThreadID; threadID != "" {
		body["input"] = map[string]any{"threadId": threadID}
	}
	actor, _ := s.upsert(body, true)
	return actor
}

func (s *neoActorStore) shouldBootstrapThreadActorForGatewayGet(r *http.Request, threadID string) bool {
	if s == nil || s.runtime == nil || r == nil || !neoThreadIDExactPattern.MatchString(threadID) {
		return false
	}
	if !strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		return false
	}
	cfg := s.runtime.configSnapshot()
	return neoRuntimeEnabled(cfg)
}

func neoWebLocalInferenceBootstrapExecutorRequested(r *http.Request, actor *neoActor) bool {
	if !neoWebLocalInferenceSocketRequested(r, actor) || r == nil || r.URL == nil {
		return false
	}
	value := strings.TrimSpace(r.URL.Query().Get("cliproxy-bootstrap-executor"))
	return value == "1" || strings.EqualFold(value, "true")
}

func neoApplyWebLocalInferenceBootstrapQuery(r *http.Request, actor *neoActor) {
	if !neoWebLocalInferenceBootstrapExecutorRequested(r, actor) {
		return
	}
	query := r.URL.Query()
	workingDirectory := neoExistingDirectory(query.Get("cliproxy-working-directory"))
	agentMode := strings.ToLower(strings.TrimSpace(query.Get("cliproxy-agent-mode")))
	reasoningEffort := strings.ToLower(strings.TrimSpace(query.Get("cliproxy-reasoning-effort")))
	if agentMode != "" && !validNeoClientAgentMode(agentMode) {
		agentMode = ""
	}

	actor.mu.Lock()
	defer actor.mu.Unlock()
	modeDefaultAllowed := !actor.hasUserTurnLocked() && stringValue(actor.settings["agentMode"]) == ""
	if workingDirectory == "" && neoExistingDirectory(neoWorkingDirectoryFromEnvironment(actor.environment)) == "" {
		workingDirectory = neoDefaultWebLocalWorkingDirectory()
	}
	if workingDirectory != "" {
		if actor.environment == nil {
			actor.environment = map[string]any{}
		}
		actor.environment["workingDirectory"] = workingDirectory
		actor.environment["workspaceRoot"] = workingDirectory
	}
	if agentMode != "" && modeDefaultAllowed {
		actor.currentAgentMode = agentMode
		actor.currentReasoningEffort = defaultNeoReasoningEffort(agentMode)
		if actor.settings == nil {
			actor.settings = map[string]any{}
		}
		actor.settings["agentMode"] = agentMode
		if actor.currentReasoningEffort == "" {
			delete(actor.settings, "reasoning.effort")
		} else {
			actor.settings["reasoning.effort"] = actor.currentReasoningEffort
		}
	}
	mode := agentMode
	if mode == "" {
		mode = actor.agentModeLocked()
	}
	if reasoningEffort != "" && modeDefaultAllowed && neoReasoningEffortAllowedForMode(mode, reasoningEffort) {
		actor.currentReasoningEffort = reasoningEffort
		if actor.settings == nil {
			actor.settings = map[string]any{}
		}
		actor.settings["reasoning.effort"] = reasoningEffort
	}
	if strings.TrimSpace(actor.bootstrapExecutorType) == "" {
		actor.bootstrapExecutorType = "local-client"
	}
}

func neoDefaultWebLocalWorkingDirectory() string {
	if home, err := os.UserHomeDir(); err == nil {
		return neoExistingDirectory(home)
	}
	return ""
}

func neoWebLocalInferenceSocketRequested(r *http.Request, actor *neoActor) bool {
	if r == nil || r.URL == nil || actor == nil || !neoGatewayThreadActorTarget(actor.name) {
		return false
	}
	if actor.runtime == nil {
		return false
	}
	cfg := actor.runtime.configSnapshot()
	if cfg == nil || !cfg.AmpCode.WebLocalInference.Enabled {
		return false
	}
	if strings.TrimSpace(r.Header.Get(neoInternalClientAPIKeyHeader)) == "" {
		return false
	}
	if strings.EqualFold(strings.TrimSpace(r.URL.Query().Get("cliproxy-client")), "amp-web-local-inference") {
		return true
	}
	origin := strings.TrimSpace(r.Header.Get("Origin"))
	return ampWebLocalInferenceRequestOriginAllowed(origin, cfg.AmpCode.WebLocalInference)
}

func (s *neoActorStore) gatewayThreadActorWithCloudState(r *http.Request, actor *neoActor, target, key string) *neoActor {
	if s == nil || actor == nil || s.runtime == nil {
		return actor
	}
	actor.mu.Lock()
	actorName := actor.name
	threadID := actor.threadID
	hasState := actor.hasLocalThreadStateLocked()
	actor.mu.Unlock()
	if !neoGatewayThreadActorTarget(target) && !neoGatewayThreadActorTarget(actorName) {
		return actor
	}
	if hasState {
		return actor
	}
	if threadID == "" {
		threadID = neoThreadIDFromGatewayKey(key)
	}
	if !neoThreadIDExactPattern.MatchString(threadID) {
		return actor
	}
	if s.runtime.tryImportNeoCloudLocalThreadActor(neoRequestContextWithClientAPIKey(r), threadID) {
		if imported := s.lookupThreadActor(threadID); imported != nil {
			return imported
		}
	}
	return actor
}

func neoGatewayThreadActorTarget(target string) bool {
	return target == "threadActor" || target == "thread-actor"
}

func neoGatewayUserActorTarget(target string) bool {
	return target == "userActor" || target == "user-actor"
}

func neoCanonicalActorName(name string) string {
	if neoGatewayThreadActorTarget(name) {
		return "thread-actor"
	}
	return name
}

func neoThreadIDFromGatewayKey(key string) string {
	for _, part := range strings.Split(key, ",") {
		part = strings.TrimSpace(part)
		if neoThreadIDExactPattern.MatchString(part) {
			return part
		}
	}
	return ""
}

func neoGatewayTargetFromPath(path string) string {
	if !strings.HasPrefix(path, "/gateway/") {
		return ""
	}
	rest := strings.TrimPrefix(path, "/gateway/")
	segment, _, _ := strings.Cut(rest, "/")
	return neoActorPathID(segment)
}

func decodeNeoGatewayInput(value string) any {
	value = strings.TrimSpace(value)
	if value == "" {
		return nil
	}
	data, err := base64.RawURLEncoding.DecodeString(value)
	if err != nil {
		data, err = base64.URLEncoding.DecodeString(value)
	}
	if err != nil {
		return nil
	}
	var decoded any
	if err := json.Unmarshal(data, &decoded); err != nil {
		return nil
	}
	return decoded
}

func (s *neoActorStore) threadActors(limit int) []*neoActor {
	s.mu.RLock()
	defer s.mu.RUnlock()
	actors := make([]*neoActor, 0, len(s.actors))
	for _, actor := range s.actors {
		if actor != nil && neoGatewayThreadActorTarget(actor.name) && neoThreadIDExactPattern.MatchString(actor.threadID) {
			actors = append(actors, actor)
		}
	}
	sort.Slice(actors, func(i, j int) bool {
		left := actors[i].lastUsedAt()
		right := actors[j].lastUsedAt()
		if !left.Equal(right) {
			return left.After(right)
		}
		return actors[i].threadID < actors[j].threadID
	})
	if limit > 0 && len(actors) > limit {
		actors = actors[:limit]
	}
	return actors
}

func (s *neoActorStore) recentThreadStatuses(limit, sinceMs int) []any {
	actors := s.threadActors(0)
	statuses := make([]any, 0, len(actors))
	for _, actor := range actors {
		status, updatedMs := actor.recentThreadStatus()
		if len(status) == 0 {
			continue
		}
		if sinceMs > 0 && updatedMs > 0 && updatedMs < sinceMs {
			continue
		}
		statuses = append(statuses, status)
	}
	s.mu.RLock()
	for _, entry := range s.recent {
		if len(entry.status) == 0 {
			continue
		}
		if sinceMs > 0 && entry.updatedMs > 0 && entry.updatedMs < sinceMs {
			continue
		}
		statuses = append(statuses, cloneMap(entry.status))
	}
	s.mu.RUnlock()
	statuses = neoDedupeRecentThreadStatuses(statuses)
	sort.Slice(statuses, func(i, j int) bool {
		left := neoTimeStringMillis(stringValue(mapValue(statuses[i])["lastUserMessageAt"]))
		right := neoTimeStringMillis(stringValue(mapValue(statuses[j])["lastUserMessageAt"]))
		if left != right {
			return left > right
		}
		return stringValue(mapValue(statuses[i])["threadId"]) < stringValue(mapValue(statuses[j])["threadId"])
	})
	if limit > 0 && len(statuses) > limit {
		statuses = statuses[:limit]
	}
	return statuses
}

func (s *neoActorStore) upsertRecentThreadStatus(status map[string]any, updatedMs int) {
	if s == nil || len(status) == 0 {
		return
	}
	threadID := strings.TrimSpace(stringValue(status["threadId"]))
	if !neoThreadIDExactPattern.MatchString(threadID) {
		return
	}
	s.mu.Lock()
	if s.recent == nil {
		s.recent = map[string]neoRecentThreadStatus{}
	}
	existing := s.recent[threadID]
	if existing.updatedMs > updatedMs {
		s.mu.Unlock()
		return
	}
	s.recent[threadID] = neoRecentThreadStatus{status: cloneMap(status), updatedMs: updatedMs}
	s.mu.Unlock()
}

func neoDedupeRecentThreadStatuses(statuses []any) []any {
	if len(statuses) < 2 {
		return statuses
	}
	out := make([]any, 0, len(statuses))
	byID := map[string]int{}
	for _, rawStatus := range statuses {
		status := mapValue(rawStatus)
		threadID := stringValue(status["threadId"])
		if threadID == "" {
			out = append(out, rawStatus)
			continue
		}
		index, exists := byID[threadID]
		if !exists {
			byID[threadID] = len(out)
			out = append(out, rawStatus)
			continue
		}
		if neoTimeStringMillis(stringValue(status["lastUserMessageAt"])) > neoTimeStringMillis(stringValue(mapValue(out[index])["lastUserMessageAt"])) {
			out[index] = rawStatus
		}
	}
	return out
}

func (s *neoActorStore) userActors() []*neoActor {
	s.mu.RLock()
	defer s.mu.RUnlock()
	actors := make([]*neoActor, 0)
	for _, actor := range s.actors {
		if actor != nil && neoGatewayUserActorTarget(actor.name) {
			actors = append(actors, actor)
		}
	}
	return actors
}

func (s *neoActorStore) userExecutorRunners() []any {
	if s == nil {
		return []any{}
	}
	byID := map[string]any{}
	for _, actor := range s.userActors() {
		for _, rawRunner := range actor.userExecutorRunners() {
			runner := mapValue(rawRunner)
			if runnerID := stringValue(runner["runnerId"]); runnerID != "" {
				byID[runnerID] = runner
			}
		}
	}
	runnerIDs := make([]string, 0, len(byID))
	for runnerID := range byID {
		runnerIDs = append(runnerIDs, runnerID)
	}
	sort.Strings(runnerIDs)
	runners := make([]any, 0, len(runnerIDs))
	for _, runnerID := range runnerIDs {
		runners = append(runners, byID[runnerID])
	}
	return runners
}

func (s *neoActorStore) userExecutorRunnerWorkingDirectory(runnerID string) string {
	for _, rawRunner := range s.userExecutorRunners() {
		runner := mapValue(rawRunner)
		if stringValue(runner["runnerId"]) == runnerID {
			return neoExistingDirectory(stringValue(runner["workingDirectory"]))
		}
	}
	return ""
}

func (s *neoActorStore) requestUserExecutorRunnerThread(runnerID, threadID string) bool {
	if s == nil || runnerID == "" {
		return false
	}
	for _, actor := range s.userActors() {
		if actor.requestUserExecutorRunnerThread(runnerID, threadID) {
			return true
		}
	}
	return false
}

func (s *neoActorStore) broadcastThreadStatusUpdated(actor *neoActor) {
	if s == nil || actor == nil || !neoGatewayThreadActorTarget(actor.name) {
		return
	}
	status, _ := actor.recentThreadStatus()
	if len(status) == 0 {
		return
	}
	payload := cloneMap(status)
	payload["type"] = "threadStatusUpdated"
	for _, userActor := range s.userActors() {
		userActor.broadcast(payload)
	}
}

func (s *neoActorStore) skillsResponse(actorID string, q url.Values) map[string]any {
	actor := s.findActorForRequest(actorID, q)
	if actor == nil {
		return map[string]any{"ok": true, "skills": []any{}, "errors": []any{}}
	}
	return actor.skillsResponse()
}

func (s *neoActorStore) findActorForRequest(actorID string, q url.Values) *neoActor {
	s.mu.RLock()
	defer s.mu.RUnlock()

	if actorID != "" {
		if actor := s.actors[actorID]; actor != nil {
			return actor
		}
		for _, actor := range s.actors {
			if actor.threadID == actorID || actor.key == actorID {
				return actor
			}
		}
	}
	match := func(value string) *neoActor {
		for _, candidate := range strings.Split(value, ",") {
			candidate = strings.TrimSpace(candidate)
			if candidate == "" {
				continue
			}
			for _, actor := range s.actors {
				if actor.threadID == candidate || actor.key == candidate || actor.id == candidate {
					return actor
				}
			}
		}
		return nil
	}
	for _, key := range []string{"threadID", "threadId", "thread_id", "key", "rvt-key", "actorID", "actorId", "actor_id"} {
		if value := strings.TrimSpace(q.Get(key)); value != "" {
			if actor := match(value); actor != nil {
				return actor
			}
		}
	}
	for _, values := range q {
		for _, value := range values {
			if actor := match(value); actor != nil {
				return actor
			}
		}
	}
	var latest *neoActor
	var latestCreated string
	for _, actor := range s.actors {
		created := stringValue(actor.record["create_ts"])
		if latest == nil || created > latestCreated {
			latest = actor
			latestCreated = created
		}
	}
	return latest
}

func (s *neoActorStore) findActors(q url.Values) []map[string]any {
	s.mu.RLock()
	defer s.mu.RUnlock()

	if ids := strings.TrimSpace(q.Get("actor_ids")); ids != "" {
		out := make([]map[string]any, 0)
		for _, id := range strings.Split(ids, ",") {
			if actor := s.actors[strings.TrimSpace(id)]; actor != nil {
				out = append(out, actor.record)
			}
		}
		return out
	}

	name := q.Get("name")
	canonicalName := neoCanonicalActorName(name)
	key, hasKey := q["key"]
	if name != "" && hasKey {
		id := s.byNameKey[canonicalName+"\x00"+firstString(key)]
		if actor := s.actors[id]; actor != nil {
			return []map[string]any{actor.record}
		}
		return nil
	}

	out := make([]map[string]any, 0, len(s.actors))
	for _, actor := range s.actors {
		if name == "" || neoCanonicalActorName(actor.name) == canonicalName {
			out = append(out, actor.record)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		return fmt.Sprint(out[i]["create_ts"]) < fmt.Sprint(out[j]["create_ts"])
	})
	return out
}

func (s *neoActorStore) upsert(body map[string]any, reuse bool) (*neoActor, bool) {
	s.mu.Lock()

	name := stringValue(body["name"])
	if name == "" {
		name = "thread-actor"
	}
	name = neoCanonicalActorName(name)
	key := stringValue(body["key"])
	if reuse && key != "" {
		if id := s.byNameKey[name+"\x00"+key]; id != "" {
			if existing := s.actors[id]; existing != nil {
				existing.touch()
				rt := s.runtime
				storeDir := ""
				if rt != nil {
					storeDir = rt.threadDir
				}
				s.mu.Unlock()
				if rt != nil && neoThreadIDExactPattern.MatchString(existing.threadID) {
					rt.autoImportThreadActor(existing, existing.threadID, storeDir)
				}
				return existing, false
			}
		}
	}

	id := "actor-" + randomBase62(22)
	threadID := extractThreadIDFromActorBody(body, key)
	record := neoActorRecord(id, name, key)
	actor := newNeoActor(s.runtime, id, name, key, threadID, record, body)
	s.actors[id] = actor
	if key != "" {
		s.byNameKey[name+"\x00"+key] = id
		if neoGatewayThreadActorTarget(name) {
			s.byNameKey["threadActor\x00"+key] = id
		}
	}
	rt := s.runtime
	storeDir := ""
	if rt != nil {
		storeDir = rt.threadDir
	}
	s.mu.Unlock()
	if rt != nil && neoThreadIDExactPattern.MatchString(threadID) {
		rt.autoImportThreadActor(actor, threadID, storeDir)
	}
	return actor, true
}

func (rt *neoRuntime) autoImportThreadActor(actor *neoActor, threadID, storeDir string) {
	if actor == nil || !rt.localThreadSnapshotsEnabled() {
		return
	}
	actor.mu.Lock()
	alreadyHydrated := actor.hasLocalThreadStateLocked()
	actor.mu.Unlock()
	if alreadyHydrated {
		return
	}
	thread, ok := loadNeoThreadFromDir(threadID, storeDir)
	if !ok || len(thread) == 0 {
		return
	}
	actor.mu.Lock()
	alreadyHydrated = actor.hasLocalThreadStateLocked()
	actor.mu.Unlock()
	if alreadyHydrated {
		return
	}
	if err := actor.importThreadLocalOnlyIfEmpty(thread); err != nil {
		log.Debugf("amp neo local runtime auto-import failed thread=%s: %v", threadID, err)
	}
}

func (a *neoActor) hasLocalThreadState() bool {
	if a == nil {
		return false
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.hasLocalThreadStateLocked()
}

func (a *neoActor) hasLocalThreadStateLocked() bool {
	return len(a.messages) > 0 ||
		len(a.queue) > 0 ||
		len(a.pendingTools) > 0 ||
		len(a.approvalQueue) > 0 ||
		len(a.pluginUIRequests) > 0 ||
		len(a.artifacts) > 0 ||
		len(a.kv) > 0 ||
		len(a.compactionRecords) > 0 ||
		len(a.relationships) > 0 ||
		len(a.meta) > 0 ||
		len(a.debug) > 0 ||
		len(a.draft) > 0 ||
		a.currentInference != nil ||
		a.pendingInference != nil ||
		a.maxTokens != nil ||
		a.mainThreadID != "" ||
		a.pendingNavigation != "" ||
		a.autoSubmitDraft ||
		a.title != "" ||
		a.archived ||
		a.threadStatus != "" ||
		a.activeErrorSeq > 0
}

func (a *neoActor) hasLocalThreadBootstrapState() bool {
	if a == nil {
		return false
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.hasLocalThreadStateLocked() ||
		len(a.settings) > 0 ||
		a.currentAgentMode != "" ||
		a.currentReasoningEffort != "" ||
		a.bootstrapExecutorType != "" ||
		a.bootstrapThreadActorFlow
}

func (s *neoActorStore) lookupThreadActor(threadID string) *neoActor {
	if s == nil || strings.TrimSpace(threadID) == "" {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, actor := range s.actors {
		if actor.threadID == threadID || actor.key == threadID {
			return actor
		}
	}
	return nil
}

func (s *neoActorStore) ensureThreadActor(threadID string) *neoActor {
	return s.ensureThreadActorWithLocalImport(threadID, true)
}

func (s *neoActorStore) ensureThreadActorWithLocalImport(threadID string, importLocal bool) *neoActor {
	s.mu.Lock()
	for _, actor := range s.actors {
		if actor.threadID == threadID || actor.key == threadID {
			rt := s.runtime
			storeDir := ""
			if rt != nil {
				storeDir = rt.threadDir
			}
			s.mu.Unlock()
			if importLocal && rt != nil && neoThreadIDExactPattern.MatchString(threadID) {
				rt.autoImportThreadActor(actor, threadID, storeDir)
			}
			return actor
		}
	}

	id := "actor-" + randomBase62(22)
	name := "thread-actor"
	record := neoActorRecord(id, name, threadID)
	actor := newNeoActor(s.runtime, id, name, threadID, threadID, record, map[string]any{"input": map[string]any{"threadId": threadID}})
	s.actors[id] = actor
	s.byNameKey[name+"\x00"+threadID] = id
	s.byNameKey["threadActor\x00"+threadID] = id
	rt := s.runtime
	storeDir := ""
	if rt != nil {
		storeDir = rt.threadDir
	}
	s.mu.Unlock()
	if importLocal && rt != nil && neoThreadIDExactPattern.MatchString(threadID) {
		rt.autoImportThreadActor(actor, threadID, storeDir)
	}
	return actor
}

func (s *neoActorStore) delete(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if actor := s.actors[id]; actor != nil {
		actor.dispose()
		if actor.key != "" {
			delete(s.byNameKey, actor.name+"\x00"+actor.key)
		}
	}
	delete(s.actors, id)
}

func (s *neoActorStore) disposeAll(stopExecutors bool, closeReason string, transportClose bool) {
	if s == nil {
		return
	}
	s.mu.Lock()
	actors := make([]*neoActor, 0, len(s.actors))
	for _, actor := range s.actors {
		actors = append(actors, actor)
	}
	s.actors = map[string]*neoActor{}
	s.byNameKey = map[string]string{}
	s.mu.Unlock()
	for _, actor := range actors {
		actor.disposeWithOptions(stopExecutors, closeReason, transportClose)
	}
}

func (s *neoActorStore) stopAllSpawnedExecutors(preserveWork bool) {
	if s == nil {
		return
	}
	s.mu.RLock()
	actors := make([]*neoActor, 0, len(s.actors))
	for _, actor := range s.actors {
		actors = append(actors, actor)
	}
	s.mu.RUnlock()
	for _, actor := range actors {
		if preserveWork {
			actor.stopSpawnedExecutorsForRebind()
		} else {
			actor.stopSpawnedExecutors()
		}
	}
}

func (s *neoActorStore) disconnectAllExecutors() {
	if s == nil {
		return
	}
	s.mu.RLock()
	actors := make([]*neoActor, 0, len(s.actors))
	for _, actor := range s.actors {
		actors = append(actors, actor)
	}
	s.mu.RUnlock()
	for _, actor := range actors {
		actor.disconnectExecutorForStop()
	}
}

func (s *neoActorStore) closeAllSockets(closeReason string, transportClose bool) {
	if s == nil {
		return
	}
	s.mu.RLock()
	actors := make([]*neoActor, 0, len(s.actors))
	for _, actor := range s.actors {
		actors = append(actors, actor)
	}
	s.mu.RUnlock()
	for _, actor := range actors {
		actor.closeSocketsWithOptions(closeReason, transportClose)
	}
}

func (s *neoActorStore) preserveExecutorWorkOnClose() {
	if s == nil {
		return
	}
	s.mu.RLock()
	actors := make([]*neoActor, 0, len(s.actors))
	for _, actor := range s.actors {
		actors = append(actors, actor)
	}
	s.mu.RUnlock()
	for _, actor := range actors {
		actor.mu.Lock()
		actor.reconnectGeneration++
		actor.preserveExecutorWorkOnClose = true
		resumeExecutorID := firstNonEmptyString(actor.resumeExecutorID, actor.executorID)
		if resumeExecutorID != "" {
			if actor.meta == nil {
				actor.meta = map[string]any{}
			}
			actor.meta[neoResumeExecutorIDMetaKey] = resumeExecutorID
		}
		actor.mu.Unlock()
	}
}

func (s *neoActorStore) syncLocalThreadSnapshots() {
	if s == nil {
		return
	}
	s.mu.RLock()
	actors := make([]*neoActor, 0, len(s.actors))
	for _, actor := range s.actors {
		actors = append(actors, actor)
	}
	s.mu.RUnlock()
	for _, actor := range actors {
		actor.syncLocalThreadSnapshotForShutdownNow()
	}
}

func (s *neoActorStore) closeLocalSnapshotSyncs() {
	if s == nil {
		return
	}
	s.mu.RLock()
	actors := make([]*neoActor, 0, len(s.actors))
	for _, actor := range s.actors {
		actors = append(actors, actor)
	}
	s.mu.RUnlock()
	for _, actor := range actors {
		actor.closeLocalSnapshotSyncs()
	}
}

func (s *neoActorStore) pruneIdle(now time.Time, ttl time.Duration) int {
	if s == nil || ttl <= 0 {
		return 0
	}
	localThreadSnapshotsEnabled := s.runtime != nil && s.runtime.localThreadSnapshotsEnabled()
	type candidate struct {
		id        string
		actor     *neoActor
		persisted bool
	}
	s.mu.RLock()
	candidates := make([]candidate, 0)
	for id, actor := range s.actors {
		if actor == nil || !actor.prunable(now, ttl, localThreadSnapshotsEnabled) {
			continue
		}
		candidates = append(candidates, candidate{id: id, actor: actor})
	}
	s.mu.RUnlock()

	for i := range candidates {
		actor := candidates[i].actor
		if !actor.hasLocalThreadState() {
			candidates[i].persisted = true
			continue
		}
		if actor.localThreadSnapshotsEnabled() {
			candidates[i].persisted = actor.syncLocalThreadSnapshotForShutdownNow()
		}
	}

	s.mu.Lock()
	stale := make([]*neoActor, 0, len(candidates))
	for _, candidate := range candidates {
		actor := candidate.actor
		if !candidate.persisted || s.actors[candidate.id] != actor || !actor.prunable(now, ttl, localThreadSnapshotsEnabled) {
			continue
		}
		stale = append(stale, actor)
		delete(s.actors, candidate.id)
		if actor.key != "" {
			delete(s.byNameKey, actor.name+"\x00"+actor.key)
		}
	}
	s.mu.Unlock()

	for _, actor := range stale {
		actor.dispose()
	}
	return len(stale)
}

