func normalizeNeoOrbServicesEnsurePayload(raw any) (map[string]any, bool) {
	value, ok := asMap(raw)
	if !ok {
		return nil, false
	}
	okValue, ok := value["ok"].(bool)
	if !ok {
		return nil, false
	}
	noConfig, ok := value["noConfig"].(bool)
	if !ok {
		return nil, false
	}
	services, ok := arrayValueOK(value["services"])
	if !ok {
		return nil, false
	}
	normalizedServices := make([]any, 0, len(services))
	for _, rawService := range services {
		service, ok := normalizeNeoOrbService(rawService)
		if !ok {
			return nil, false
		}
		normalizedServices = append(normalizedServices, service)
	}
	out := map[string]any{"ok": okValue, "noConfig": noConfig, "services": normalizedServices}
	if errText, exists := value["error"]; exists {
		if _, ok := errText.(string); !ok {
			return nil, false
		}
		out["error"] = errText
	}
	return out, true
}

func normalizeNeoOrbService(raw any) (map[string]any, bool) {
	value, ok := asMap(raw)
	if !ok {
		return nil, false
	}
	name, ok := value["name"].(string)
	if !ok {
		return nil, false
	}
	okValue, ok := value["ok"].(bool)
	if !ok {
		return nil, false
	}
	portals, ok := arrayValueOK(value["portals"])
	if !ok {
		return nil, false
	}
	normalizedPortals := make([]any, 0, len(portals))
	for _, rawPortal := range portals {
		portal, ok := normalizeNeoOrbPortal(rawPortal)
		if !ok {
			return nil, false
		}
		normalizedPortals = append(normalizedPortals, portal)
	}
	out := map[string]any{"name": name, "ok": okValue, "portals": normalizedPortals}
	for _, key := range []string{"error", "baseURL", "healthError"} {
		if value, exists := value[key]; exists {
			if _, ok := value.(string); !ok {
				return nil, false
			}
			out[key] = value
		}
	}
	for _, key := range []string{"port", "healthStatus"} {
		if value, exists := value[key]; exists {
			if _, ok := neoProtocolInteger(value); !ok {
				return nil, false
			}
			out[key] = value
		}
	}
	return out, true
}

func normalizeNeoOrbPortal(raw any) (map[string]any, bool) {
	value, ok := asMap(raw)
	if !ok {
		return nil, false
	}
	title, titleOK := value["title"].(string)
	urlValue, urlOK := value["url"].(string)
	if !titleOK || !urlOK {
		return nil, false
	}
	out := map[string]any{"title": title, "url": urlValue}
	if description, exists := value["description"]; exists {
		if _, ok := description.(string); !ok {
			return nil, false
		}
		out["description"] = description
	}
	return out, true
}

func neoProtocolInteger(raw any) (int, bool) {
	switch value := raw.(type) {
	case int:
		return value, true
	case int8:
		return int(value), true
	case int16:
		return int(value), true
	case int32:
		return int(value), true
	case int64:
		converted := int(value)
		return converted, int64(converted) == value
	case uint:
		converted := int(value)
		return converted, converted >= 0 && uint(converted) == value
	case uint8:
		return int(value), true
	case uint16:
		return int(value), true
	case uint32:
		converted := int(value)
		return converted, converted >= 0 && uint32(converted) == value
	case uint64:
		converted := int(value)
		return converted, converted >= 0 && uint64(converted) == value
	case float64:
		converted := int(value)
		return converted, float64(converted) == value
	case json.Number:
		parsed, err := value.Int64()
		if err != nil {
			return 0, false
		}
		converted := int(parsed)
		return converted, int64(converted) == parsed
	default:
		return 0, false
	}
}

func arrayValueOK(raw any) ([]any, bool) {
	values, ok := raw.([]any)
	return values, ok
}

func normalizeNeoFilesystemEntries(raw any) ([]any, bool) {
	items, ok := raw.([]any)
	if !ok {
		return nil, false
	}
	out := make([]any, 0, len(items))
	for _, item := range items {
		entry, ok := normalizeNeoFilesystemEntry(item)
		if !ok {
			return nil, false
		}
		out = append(out, entry)
	}
	return out, true
}

func normalizeNeoFilesystemEntry(raw any) ([]any, bool) {
	entry, ok := raw.([]any)
	if !ok || len(entry) < 2 || len(entry) > 3 {
		return nil, false
	}
	path, ok := entry[0].(string)
	if !ok {
		return nil, false
	}
	entryType, ok := entry[1].(string)
	if !ok || (entryType != "file" && entryType != "directory") {
		return nil, false
	}
	out := []any{path, entryType}
	if len(entry) == 3 {
		if entry[2] == nil {
			out = append(out, nil)
			return out, true
		}
		meta, ok := normalizeNeoFilesystemEntryMetadata(entry[2])
		if !ok {
			return nil, false
		}
		out = append(out, meta)
	}
	return out, true
}

func normalizeNeoFilesystemEntryMetadata(raw any) (map[string]any, bool) {
	meta, ok := asMap(raw)
	if !ok {
		return nil, false
	}
	out := map[string]any{}
	if value, exists := meta["mtimeMs"]; exists {
		number, ok := neoNumberSettingFloat(value)
		if !ok || number < 0 {
			return nil, false
		}
		out["mtimeMs"] = value
	}
	return out, true
}

func normalizeNeoFilesystemError(raw any) (map[string]any, bool) {
	errPayload, ok := asMap(raw)
	if !ok {
		return nil, false
	}
	code, ok := errPayload["code"].(string)
	if !ok || !validNeoFilesystemErrorCode(code) {
		return nil, false
	}
	message, ok := errPayload["message"].(string)
	if !ok {
		return nil, false
	}
	return map[string]any{"code": code, "message": message}, true
}

func validNeoFilesystemErrorCode(code string) bool {
	switch code {
	case "INVALID_URI", "EXECUTOR_NOT_CONNECTED", "NOT_FOUND", "NOT_DIRECTORY", "IS_DIRECTORY", "TOO_LARGE", "ACCESS_DENIED", "INTERNAL_ERROR":
		return true
	default:
		return false
	}
}

// neoRetypedMessage clones a protocol message and re-types it for the opposite side
// of the client/executor bridge. The git-diff-snapshot feature (added in Amp g0a52b8)
// is executor-computed, so the local runtime relays the request/result pair across the
// bridge rather than running the diff itself, matching the filesystem/git_command relays.
func neoRetypedMessage(msg map[string]any, newType string) map[string]any {
	out := cloneMap(msg)
	out["type"] = newType
	return out
}

func neoTerminalBridgeType(msgType string) (string, bool) {
	switch msgType {
	case "client_terminal_open":
		return "executor_terminal_open", true
	case "client_terminal_input":
		return "executor_terminal_input", true
	case "client_terminal_resize":
		return "executor_terminal_resize", true
	case "client_terminal_close":
		return "executor_terminal_close", true
	case "client_terminal_output":
		return "executor_terminal_output", true
	case "client_terminal_exit":
		return "executor_terminal_exit", true
	case "executor_terminal_open":
		return "client_terminal_open", true
	case "executor_terminal_input":
		return "client_terminal_input", true
	case "executor_terminal_resize":
		return "client_terminal_resize", true
	case "executor_terminal_close":
		return "client_terminal_close", true
	case "executor_terminal_output":
		return "client_terminal_output", true
	case "executor_terminal_exit":
		return "client_terminal_exit", true
	default:
		return "", false
	}
}

func normalizeNeoClientGitCommand(msg map[string]any) (map[string]any, bool) {
	requestID, ok := neoRequiredString(msg["requestId"])
	if !ok {
		return nil, false
	}
	operation, ok := normalizeNeoGitOperation(msg["operation"])
	if !ok {
		return nil, false
	}
	return map[string]any{"type": "client_git_command", "requestId": requestID, "operation": operation}, true
}

func normalizeNeoExecutorGitCommand(msg map[string]any) (map[string]any, bool) {
	requestID, ok := neoRequiredString(msg["requestId"])
	if !ok {
		return nil, false
	}
	args, ok := normalizeNeoStringArray(msg["args"], true)
	if !ok {
		return nil, false
	}
	out := map[string]any{"type": "executor_git_command", "requestId": requestID, "args": args}
	if value, exists := msg["maxOutputBytes"]; exists {
		number, ok := neoClientNumber(value)
		if !ok || number <= 0 {
			return nil, false
		}
		out["maxOutputBytes"] = number
	}
	if value, exists := msg["operation"]; exists {
		operation, ok := normalizeNeoGitOperation(value)
		if !ok {
			return nil, false
		}
		out["operation"] = operation
	}
	return out, true
}

func normalizeNeoGitOperation(raw any) (map[string]any, bool) {
	operation, ok := asMap(raw)
	if !ok {
		return nil, false
	}
	operationType, ok := operation["type"].(string)
	if !ok {
		return nil, false
	}
	switch operationType {
	case "repository_root", "head", "branch", "status", "status_snapshot", "comparison_base_ref", "comparison_base_head", "ahead_count", "behind_count", "ahead_commits":
		return map[string]any{"type": operationType}, true
	case "diff_range_snapshot":
		baseHash, ok := operation["baseHash"].(string)
		if !ok || !neoGitHashPattern.MatchString(baseHash) {
			return nil, false
		}
		out := map[string]any{"type": operationType, "baseHash": baseHash}
		if value, exists := operation["headHash"]; exists {
			headHash, ok := value.(string)
			if !ok || !neoGitHashPattern.MatchString(headHash) {
				return nil, false
			}
			out["headHash"] = headHash
		}
		return out, true
	case "file_diff":
		path, ok := operation["path"].(string)
		if !ok || path == "" {
			return nil, false
		}
		changeType, ok := operation["changeType"].(string)
		if !ok || !validNeoGitChangeType(changeType) {
			return nil, false
		}
		full, ok := operation["full"].(bool)
		if !ok {
			return nil, false
		}
		return map[string]any{"type": operationType, "path": path, "changeType": changeType, "full": full}, true
	default:
		return nil, false
	}
}

func validNeoGitChangeType(changeType string) bool {
	switch changeType {
	case "added", "modified", "deleted", "renamed", "copied", "type_changed", "unmerged", "untracked":
		return true
	default:
		return false
	}
}

func normalizeNeoGitCommandResult(outboundType string, msg map[string]any) (map[string]any, bool) {
	requestID, ok := neoRequiredString(msg["requestId"])
	if !ok {
		return nil, false
	}
	okValue, ok := msg["ok"].(bool)
	if !ok {
		return nil, false
	}
	out := map[string]any{"type": outboundType, "requestId": requestID, "ok": okValue}
	if okValue {
		exitCode, ok := neoClientNumber(msg["exitCode"])
		if !ok || exitCode < 0 {
			return nil, false
		}
		stdout, ok := msg["stdout"].(string)
		if !ok {
			return nil, false
		}
		stderr, ok := msg["stderr"].(string)
		if !ok {
			return nil, false
		}
		if _, exists := msg["error"]; exists {
			return nil, false
		}
		out["exitCode"] = exitCode
		out["stdout"] = stdout
		out["stderr"] = stderr
		return out, true
	}
	if value, exists := msg["exitCode"]; exists {
		exitCode, ok := neoClientNumber(value)
		if !ok || exitCode < 0 {
			return nil, false
		}
		out["exitCode"] = exitCode
	}
	if value, exists := msg["stdout"]; exists {
		stdout, ok := value.(string)
		if !ok {
			return nil, false
		}
		out["stdout"] = stdout
	}
	if value, exists := msg["stderr"]; exists {
		stderr, ok := value.(string)
		if !ok {
			return nil, false
		}
		out["stderr"] = stderr
	}
	errPayload, ok := normalizeNeoGitError(msg["error"])
	if !ok {
		return nil, false
	}
	out["error"] = errPayload
	return out, true
}

func normalizeNeoGitError(raw any) (map[string]any, bool) {
	errPayload, ok := asMap(raw)
	if !ok {
		return nil, false
	}
	code, ok := errPayload["code"].(string)
	if !ok || !validNeoGitErrorCode(code) {
		return nil, false
	}
	message, ok := errPayload["message"].(string)
	if !ok {
		return nil, false
	}
	return map[string]any{"code": code, "message": message}, true
}

func validNeoGitErrorCode(code string) bool {
	switch code {
	case "EXECUTOR_NOT_CONNECTED", "INVALID_ARGS", "INTERNAL_ERROR":
		return true
	default:
		return false
	}
}

func normalizeNeoStringArray(raw any, requireNonEmpty bool) ([]any, bool) {
	items, ok := raw.([]any)
	if !ok || (requireNonEmpty && len(items) == 0) {
		return nil, false
	}
	out := make([]any, 0, len(items))
	for _, item := range items {
		value, ok := item.(string)
		if !ok {
			return nil, false
		}
		out = append(out, value)
	}
	return out, true
}

func neoRequiredString(raw any) (string, bool) {
	value, ok := raw.(string)
	if !ok || value == "" {
		return "", false
	}
	return value, true
}

func (a *neoActor) handleClientGitCommand(msg map[string]any) {
	requestID, ok := neoRequiredString(msg["requestId"])
	if !ok {
		return
	}
	operation := cloneMap(mapValue(msg["operation"]))
	a.mu.Lock()
	environment := cloneMap(a.environment)
	a.mu.Unlock()
	cwd := neoHeadlessWorkingDirectory(msg, environment)

	go func() {
		result := neoRunClientGitCommand(cwd, operation, 0)
		result["type"] = "client_git_command_result"
		result["requestId"] = requestID
		a.broadcast(result)
	}()
}

func neoRunClientGitCommand(cwd string, operation map[string]any, maxOutputBytes int) map[string]any {
	return neoRunGitOperation(cwd, operation, maxOutputBytes)
}

func neoRunGitOperation(cwd string, operation map[string]any, maxOutputBytes int) map[string]any {
	switch stringValue(operation["type"]) {
	case "status_snapshot":
		snapshot := neoGitStatusSnapshot(cwd)
		raw, err := json.Marshal(snapshot)
		if err != nil {
			return neoGitCommandError("INTERNAL_ERROR", err.Error())
		}
		return neoGitCommandOK(0, string(raw), "")
	case "comparison_base_ref":
		base, ok := neoGitComparisonBase(cwd)
		if !ok {
			return neoGitCommandOK(1, "", "comparison base ref not found\n")
		}
		return neoGitCommandOK(0, base.baseRef+"\n", "")
	case "comparison_base_head":
		base, ok := neoGitComparisonBase(cwd)
		if !ok {
			return neoGitCommandOK(1, "", "comparison base head not found\n")
		}
		return neoGitCommandOK(0, base.baseRefHead+"\n", "")
	case "ahead_count":
		return neoRunGitAheadBehindCount(cwd, true)
	case "behind_count":
		return neoRunGitAheadBehindCount(cwd, false)
	case "ahead_commits":
		return neoRunGitAheadCommits(cwd)
	case "diff_range_snapshot":
		return neoRunGitDiffRangeSnapshot(cwd, operation, maxOutputBytes)
	case "file_diff":
		return neoRunGitFileDiff(cwd, operation, maxOutputBytes)
	default:
		args, ok := neoGitArgsForOperation(operation)
		if !ok {
			return neoGitCommandError("INVALID_ARGS", "Unsupported git operation")
		}
		return neoRunGitCommand(cwd, args, maxOutputBytes, false)
	}
}

func neoGitArgsForOperation(operation map[string]any) ([]string, bool) {
	switch stringValue(operation["type"]) {
	case "repository_root":
		return []string{"rev-parse", "--show-toplevel"}, true
	case "head":
		return []string{"rev-parse", "--verify", "HEAD"}, true
	case "branch":
		return []string{"symbolic-ref", "--short", "HEAD"}, true
	case "status":
		return []string{"status", "--porcelain=v1", "--untracked-files=all", "-z"}, true
	default:
		return nil, false
	}
}

type neoGitComparisonBaseInfo struct {
	baseRef       string
	comparisonRef string
	baseRefHead   string
	mergeBaseHead string
}

func neoGitComparisonBase(cwd string) (neoGitComparisonBaseInfo, bool) {
	refResult := neoRunGitCommand(cwd, []string{"symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"}, 0, false)
	if numberFrom(refResult["exitCode"]) != 0 {
		return neoGitComparisonBaseInfo{}, false
	}
	rawRef := strings.TrimSpace(stringValue(refResult["stdout"]))
	const prefix = "refs/remotes/origin/"
	if !strings.HasPrefix(rawRef, prefix) {
		return neoGitComparisonBaseInfo{}, false
	}
	baseRef := strings.TrimPrefix(rawRef, prefix)
	if baseRef == "" {
		return neoGitComparisonBaseInfo{}, false
	}
	comparisonRef := "origin/" + baseRef
	headResult := neoRunGitCommand(cwd, []string{"rev-parse", "--verify", "--quiet", comparisonRef + "^{commit}"}, 0, false)
	if numberFrom(headResult["exitCode"]) != 0 {
		return neoGitComparisonBaseInfo{}, false
	}
	mergeBaseResult := neoRunGitCommand(cwd, []string{"merge-base", "HEAD", comparisonRef}, 0, false)
	if numberFrom(mergeBaseResult["exitCode"]) != 0 {
		return neoGitComparisonBaseInfo{}, false
	}
	return neoGitComparisonBaseInfo{
		baseRef:       baseRef,
		comparisonRef: comparisonRef,
		baseRefHead:   strings.TrimSpace(stringValue(headResult["stdout"])),
		mergeBaseHead: strings.TrimSpace(stringValue(mergeBaseResult["stdout"])),
	}, true
}

func neoRunGitAheadBehindCount(cwd string, ahead bool) map[string]any {
	base, ok := neoGitComparisonBase(cwd)
	if !ok {
		return neoGitCommandOK(1, "", "comparison base not found\n")
	}
	rangeSpec := base.comparisonRef + "..HEAD"
	if !ahead {
		rangeSpec = "HEAD.." + base.comparisonRef
	}
	return neoRunGitCommand(cwd, []string{"rev-list", "--count", rangeSpec}, 0, false)
}

func neoRunGitAheadCommits(cwd string) map[string]any {
	base, ok := neoGitComparisonBase(cwd)
	if !ok || base.mergeBaseHead == "" {
		return neoGitCommandOK(1, "", "comparison base not found\n")
	}
	return neoRunGitCommand(cwd, []string{"log", "-z", "--reverse", "--max-count=20", "--format=%H%x00%s", base.mergeBaseHead + "..HEAD"}, 0, false)
}

type neoGitDiffRangeEntry struct {
	path         string
	previousPath string
	changeType   string
}

func neoRunGitDiffRangeSnapshot(cwd string, operation map[string]any, maxOutputBytes int) map[string]any {
	capturedAt := time.Now().UnixMilli()
	rootResult := neoRunGitCommand(cwd, []string{"rev-parse", "--show-toplevel"}, 0, false)
	if numberFrom(rootResult["exitCode"]) != 0 {
		return neoGitSnapshotResult(neoUnavailableGitSnapshot(capturedAt, "not a git repository"))
	}
	root := strings.TrimSpace(stringValue(rootResult["stdout"]))
	baseHash := stringValue(operation["baseHash"])
	headHash := stringValue(operation["headHash"])
	diffArgs := []string{"diff", "--no-color", "--no-ext-diff", "--name-status", "-z", "--find-renames"}
	if headHash != "" {
		diffArgs = append(diffArgs, baseHash+".."+headHash)
	} else {
		diffArgs = append(diffArgs, baseHash)
	}
	diffResult := neoRunGitCommand(root, diffArgs, 0, false)
	if numberFrom(diffResult["exitCode"]) != 0 {
		return neoGitSnapshotResult(neoUnavailableGitSnapshot(capturedAt, "failed to read git diff range"))
	}
	entries := neoParseGitNameStatusZ(stringValue(diffResult["stdout"]))
	seen := map[string]bool{}
	for _, entry := range entries {
		seen[entry.path] = true
	}
	if headHash == "" {
		statusResult := neoRunGitCommand(root, []string{"status", "--porcelain=v1", "--untracked-files=all", "-z"}, 0, false)
		if numberFrom(statusResult["exitCode"]) == 0 {
			for _, entry := range neoParseGitPorcelainZ(stringValue(statusResult["stdout"])) {
				if entry.changeType == "untracked" && !seen[entry.path] {
					entries = append(entries, neoGitDiffRangeEntry{path: entry.path, changeType: "untracked"})
				}
			}
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].path < entries[j].path })

	files := make([]any, 0, len(entries))
	for _, entry := range entries {
		diff := neoGitDiffRangeFileDiff(root, entry, baseHash, headHash, false, maxOutputBytes)
		fullFileDiff := neoGitDiffRangeFileDiff(root, entry, baseHash, headHash, true, maxOutputBytes)
		file := map[string]any{
			"path":         entry.path,
			"previousPath": omitEmpty(entry.previousPath),
			"changeType":   entry.changeType,
			"created":      entry.changeType == "added" || entry.changeType == "untracked",
			"diffToken":    neoGitDiffRangeToken(entry, baseHash, headHash, diff),
			"diff":         diff,
			"fullFileDiff": fullFileDiff,
			"diffStat":     neoGitDiffStat(diff),
		}
		if entry.changeType != "added" && entry.changeType != "untracked" {
			if oldContent := neoGitShowFile(root, baseHash, fallbackString(entry.previousPath, entry.path), maxOutputBytes); oldContent != "" {
				file["oldContent"] = oldContent
			}
		}
		if entry.changeType != "deleted" {
			if newContent := neoGitDiffRangeNewContent(root, headHash, entry.path, maxOutputBytes); newContent != "" {
				file["newContent"] = newContent
			}
		}
		files = append(files, file)
	}

	branchResult := neoRunGitCommand(root, []string{"symbolic-ref", "--short", "HEAD"}, 0, false)
	headResult := neoRunGitCommand(root, []string{"rev-parse", "--verify", "HEAD"}, 0, false)
	head := headHash
	if head == "" {
		head = strings.TrimSpace(stringValue(headResult["stdout"]))
	}
	snapshot := map[string]any{
		"provider":       "git",
		"capturedAt":     capturedAt,
		"available":      true,
		"repositoryRoot": root,
		"repositoryName": filepath.Base(root),
		"branch":         nullableString(strings.TrimSpace(stringValue(branchResult["stdout"]))),
		"head":           nullableString(head),
		"diffHash":       neoGitDiffHash(files),
		"baseRefHead":    baseHash,
		"files":          files,
	}
	return neoGitSnapshotResult(snapshot)
}

func neoGitSnapshotResult(snapshot map[string]any) map[string]any {
	raw, err := json.Marshal(snapshot)
	if err != nil {
		return neoGitCommandError("INTERNAL_ERROR", err.Error())
	}
	return neoGitCommandOK(0, string(raw), "")
}

func neoParseGitNameStatusZ(raw string) []neoGitDiffRangeEntry {
	parts := strings.Split(raw, "\x00")
	entries := make([]neoGitDiffRangeEntry, 0, len(parts)/2)
	for i := 0; i < len(parts); {
		status := strings.TrimSpace(parts[i])
		i++
		if status == "" {
			continue
		}
		changeType := neoGitNameStatusChangeType(status)
		if changeType == "renamed" || changeType == "copied" {
			if i+1 >= len(parts) {
				break
			}
			previousPath := parts[i]
			path := parts[i+1]
			i += 2
			if path != "" {
				entries = append(entries, neoGitDiffRangeEntry{path: path, previousPath: previousPath, changeType: changeType})
			}
			continue
		}
		if i >= len(parts) {
			break
		}
		path := parts[i]
		i++
		if path != "" {
			entries = append(entries, neoGitDiffRangeEntry{path: path, changeType: changeType})
		}
	}
	return entries
}

func neoGitNameStatusChangeType(status string) string {
	switch status[0] {
	case 'A':
		return "added"
	case 'D':
		return "deleted"
	case 'R':
		return "renamed"
	case 'C':
		return "copied"
	case 'T':
		return "type_changed"
	case 'U':
		return "unmerged"
	default:
		return "modified"
	}
}

func neoGitDiffRangeFileDiff(root string, entry neoGitDiffRangeEntry, baseHash, headHash string, full bool, maxOutputBytes int) string {
	if entry.changeType == "untracked" {
		args := []string{"-c", "core.quotepath=false", "diff", "--no-color", "--no-ext-diff", "--no-index"}
		if full {
			args = append(args, "--unified=999999")
		}
		args = append(args, "--", os.DevNull, entry.path)
		result := neoRunGitCommand(root, args, maxOutputBytes, true)
		return stringValue(result["stdout"])
	}
	args := []string{"-c", "core.quotepath=false", "diff", "--no-color", "--no-ext-diff"}
	if full {
		args = append(args, "--unified=999999")
	}
	if headHash != "" {
		args = append(args, baseHash+".."+headHash)
	} else {
		args = append(args, baseHash)
	}
	args = append(args, "--", entry.path)
	result := neoRunGitCommand(root, args, maxOutputBytes, false)
	if numberFrom(result["exitCode"]) != 0 {
		return ""
	}
	return stringValue(result["stdout"])
}

func neoGitShowFile(root, revision, path string, maxOutputBytes int) string {
	if revision == "" || path == "" {
		return ""
	}
	result := neoRunGitCommand(root, []string{"show", revision + ":" + path}, maxOutputBytes, false)
	if numberFrom(result["exitCode"]) != 0 {
		return ""
	}
	return stringValue(result["stdout"])
}

func neoGitDiffRangeNewContent(root, revision, path string, maxOutputBytes int) string {
	if revision != "" {
		return neoGitShowFile(root, revision, path, maxOutputBytes)
	}
	if path == "" || strings.Contains(path, "\x00") {
		return ""
	}
	raw, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(path)))
	if err != nil {
		return ""
	}
	return neoTrimGitOutput(string(raw), maxOutputBytes)
}

func neoGitDiffRangeToken(entry neoGitDiffRangeEntry, baseHash, headHash, diff string) string {
	hash := sha256.New()
	for _, value := range []string{entry.path, entry.previousPath, entry.changeType, baseHash, headHash, diff} {
		hash.Write([]byte(value))
		hash.Write([]byte{0})
	}
	return hex.EncodeToString(hash.Sum(nil))
}

func neoRunGitFileDiff(cwd string, operation map[string]any, maxOutputBytes int) map[string]any {
	path := strings.TrimSpace(stringValue(operation["path"]))
	if path == "" || strings.Contains(path, "\x00") {
		return neoGitCommandError("INVALID_ARGS", "Git file diff path is required")
	}
	args := []string{"-c", "core.quotepath=false", "diff", "--no-color", "--no-ext-diff"}
	if boolValue(operation["full"]) {
		args = append(args, "--unified=999999")
	}
	if stringValue(operation["changeType"]) == "untracked" {
		args = append(args, "--no-index", "--", os.DevNull, path)
		result := neoRunGitCommand(cwd, args, maxOutputBytes, true)
		if numberFrom(result["exitCode"]) == 1 {
			result["exitCode"] = 0
		}
		return result
	}
	if neoGitHeadExists(cwd) {
		args = append(args, "HEAD", "--", path)
		return neoRunGitCommand(cwd, args, maxOutputBytes, false)
	}
	cached := neoRunGitCommand(cwd, append(append([]string{}, args...), "--cached", "--", path), maxOutputBytes, false)
	unstaged := neoRunGitCommand(cwd, append(append([]string{}, args...), "--", path), maxOutputBytes, false)
	stdout := strings.TrimRight(stringValue(cached["stdout"]), "\n")
	if extra := strings.TrimRight(stringValue(unstaged["stdout"]), "\n"); extra != "" {
		if stdout != "" {
			stdout += "\n"
		}
		stdout += extra
	}
	stderr := stringValue(cached["stderr"]) + stringValue(unstaged["stderr"])
	exitCode := numberFrom(cached["exitCode"])
	if exitCode == 0 {
		exitCode = numberFrom(unstaged["exitCode"])
	}
	return neoGitCommandOK(exitCode, stdout, stderr)
}

func neoGitHeadExists(cwd string) bool {
	result := neoRunGitCommand(cwd, []string{"rev-parse", "--verify", "HEAD"}, 0, false)
	return numberFrom(result["exitCode"]) == 0
}

func neoGitStatusSnapshot(cwd string) map[string]any {
	capturedAt := time.Now().UnixMilli()
	rootResult := neoRunGitCommand(cwd, []string{"rev-parse", "--show-toplevel"}, 0, false)
	if numberFrom(rootResult["exitCode"]) != 0 {
		return neoUnavailableGitSnapshot(capturedAt, "not a git repository")
	}
	root := strings.TrimSpace(stringValue(rootResult["stdout"]))
	headResult := neoRunGitCommand(root, []string{"rev-parse", "--verify", "HEAD"}, 0, false)
	branchResult := neoRunGitCommand(root, []string{"symbolic-ref", "--short", "HEAD"}, 0, false)
	statusResult := neoRunGitCommand(root, []string{"status", "--porcelain=v1", "--untracked-files=all", "-z"}, 0, false)
	if numberFrom(statusResult["exitCode"]) != 0 {
		return neoUnavailableGitSnapshot(capturedAt, "failed to read git status")
	}
	files := neoGitStatusFiles(root, strings.TrimSpace(stringValue(headResult["stdout"])), stringValue(statusResult["stdout"]))
	snapshot := map[string]any{
		"provider":       "git",
		"capturedAt":     capturedAt,
		"available":      true,
		"repositoryRoot": root,
		"repositoryName": filepath.Base(root),
		"branch":         nullableString(strings.TrimSpace(stringValue(branchResult["stdout"]))),
		"head":           nullableString(strings.TrimSpace(stringValue(headResult["stdout"]))),
		"files":          files,
		"diffHash":       neoGitDiffHash(files),
		"baseRef":        nil,
		"baseRefHead":    nil,
		"aheadCount":     0,
	}
	if base, ok := neoGitComparisonBase(root); ok {
		snapshot["baseRef"] = base.baseRef
		snapshot["baseRefHead"] = base.baseRefHead
		if ahead := neoRunGitAheadBehindCount(root, true); numberFrom(ahead["exitCode"]) == 0 {
			snapshot["aheadCount"] = numberFromString(strings.TrimSpace(stringValue(ahead["stdout"])))
		}
		if behind := neoRunGitAheadBehindCount(root, false); numberFrom(behind["exitCode"]) == 0 {
			snapshot["behindCount"] = numberFromString(strings.TrimSpace(stringValue(behind["stdout"])))
		}
		if commits := neoGitAheadCommitObjects(root, base.mergeBaseHead); commits != nil {
			snapshot["aheadCommits"] = commits
		}
	}
	return snapshot
}

func neoUnavailableGitSnapshot(capturedAt int64, reason string) map[string]any {
	return map[string]any{
		"provider":          "git",
		"capturedAt":        capturedAt,
		"available":         false,
		"repositoryRoot":    nil,
		"repositoryName":    nil,
		"branch":            nil,
		"head":              nil,
		"files":             []any{},
		"unavailableReason": reason,
	}
}

func neoGitStatusFiles(root, head, status string) []any {
	entries := neoParseGitPorcelainZ(status)
	files := make([]any, 0, len(entries))
	for _, entry := range entries {
		if entry.path == "" {
			continue
		}
		diff := ""
		if entry.changeType == "untracked" {
			result := neoRunGitFileDiff(root, map[string]any{"type": "file_diff", "path": entry.path, "changeType": entry.changeType}, 0)
			if numberFrom(result["exitCode"]) == 0 {
				diff = strings.TrimRight(stringValue(result["stdout"]), "\n")
			}
		} else if head != "" {
			result := neoRunGitFileDiff(root, map[string]any{"type": "file_diff", "path": entry.path, "changeType": entry.changeType}, 0)
			if numberFrom(result["exitCode"]) == 0 {
				diff = strings.TrimRight(stringValue(result["stdout"]), "\n")
			}
		}
		files = append(files, map[string]any{
			"path":         entry.path,
			"previousPath": omitEmpty(entry.previousPath),
			"changeType":   entry.changeType,
			"created":      entry.changeType == "added" || entry.changeType == "untracked",
			"diff":         diff,
			"diffStat":     neoGitDiffStat(diff),
		})
	}
	return files
}

type neoGitStatusEntry struct {
	path         string
	previousPath string
	changeType   string
	rawStatus    string
}

func neoParseGitPorcelainZ(status string) []neoGitStatusEntry {
	parts := strings.Split(status, "\x00")
	entries := make([]neoGitStatusEntry, 0, len(parts))
	for i := 0; i < len(parts); i++ {
		item := parts[i]
		if len(item) < 4 {
			continue
		}
		rawStatus := item[:2]
		path := item[3:]
		if path == "" || strings.HasSuffix(path, "/") {
			continue
		}
		entry := neoGitStatusEntry{path: path, changeType: neoGitChangeType(rawStatus), rawStatus: rawStatus}
		if (entry.changeType == "renamed" || entry.changeType == "copied") && i+1 < len(parts) {
			entry.previousPath = parts[i+1]
			i++
		}
		entries = append(entries, entry)
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].path < entries[j].path })
	return entries
}

func neoGitChangeType(status string) string {
	if status == "??" {
		return "untracked"
	}
	x := byte(' ')
	y := byte(' ')
	if len(status) > 0 {
		x = status[0]
	}
	if len(status) > 1 {
		y = status[1]
	}
	if x == 'U' || y == 'U' || status == "AA" || status == "DD" {
		return "unmerged"
	}
	if x == 'R' || y == 'R' {
		return "renamed"
	}
	if x == 'C' || y == 'C' {
		return "copied"
	}
	if x == 'A' || y == 'A' {
		return "added"
	}
	if x == 'D' || y == 'D' {
		return "deleted"
	}
	if x == 'T' || y == 'T' {
		return "type_changed"
	}
	return "modified"
}

func neoGitDiffStat(diff string) map[string]any {
	added := 0
	deleted := 0
	changed := 0
	pendingAdded := 0
	pendingDeleted := 0
	flush := func() {
		if pendingAdded == 0 && pendingDeleted == 0 {
			return
		}
		if pendingAdded < pendingDeleted {
			changed += pendingAdded
		} else {
			changed += pendingDeleted
		}
		pendingAdded = 0
		pendingDeleted = 0
	}
	for _, line := range strings.Split(diff, "\n") {
		if strings.HasPrefix(line, "+") && !strings.HasPrefix(line, "+++") {
			added++
			pendingAdded++
			continue
		}
		if strings.HasPrefix(line, "-") && !strings.HasPrefix(line, "---") {
			deleted++
			pendingDeleted++
			continue
		}
		flush()
	}
	flush()
	return map[string]any{"added": added, "deleted": deleted, "changed": changed}
}

func neoGitDiffHash(files []any) string {
	hash := sha256.New()
	for _, raw := range files {
		file := mapValue(raw)
		hash.Write([]byte(stringValue(file["path"])))
		hash.Write([]byte{0})
		hash.Write([]byte(stringValue(file["diffToken"])))
		if stringValue(file["diffToken"]) == "" {
			hash.Write([]byte(stringValue(file["diff"])))
		}
		hash.Write([]byte{0})
	}
	return hex.EncodeToString(hash.Sum(nil))
}

func neoGitAheadCommitObjects(cwd, mergeBase string) []any {
	if mergeBase == "" {
		return nil
	}
	result := neoRunGitCommand(cwd, []string{"log", "-z", "--reverse", "--max-count=20", "--format=%H%x00%s", mergeBase + "..HEAD"}, 0, false)
	if numberFrom(result["exitCode"]) != 0 {
		return nil
	}
	parts := strings.Split(stringValue(result["stdout"]), "\x00")
	commits := make([]any, 0, len(parts)/2)
	for i := 0; i+1 < len(parts); i += 2 {
		hash := strings.TrimSpace(parts[i])
		if hash == "" {
			continue
		}
		commits = append(commits, map[string]any{
			"hash":      hash,
			"shortHash": firstN(hash, 12),
			"subject":   parts[i+1],
			"metadata":  map[string]any{"isMergeBase": false},
		})
	}
	return commits
}

func neoRunGitCommand(cwd string, args []string, maxOutputBytes int, allowExitOne bool) map[string]any {
	if len(args) == 0 {
		return neoGitCommandError("INVALID_ARGS", "Git command arguments must be non-empty")
	}
	for _, arg := range args {
		if strings.Contains(arg, "\x00") {
			return neoGitCommandError("INVALID_ARGS", "Git command arguments must not contain NUL bytes")
		}
	}
	cmd := exec.Command("git", args...)
	if cwd != "" {
		cmd.Dir = cwd
	}
	cmd.Env = neoGitCommandEnv()
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	exitCode := 0
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			exitCode = exitErr.ExitCode()
			if allowExitOne && exitCode == 1 {
				exitCode = 0
			}
		} else {
			return neoGitCommandError("INTERNAL_ERROR", err.Error())
		}
	}
	return neoGitCommandOK(exitCode, neoTrimGitOutput(stdout.String(), maxOutputBytes), neoTrimGitOutput(stderr.String(), maxOutputBytes))
}

func neoGitCommandEnv() []string {
	base := os.Environ()
	out := make([]string, 0, len(base)+3)
	for _, item := range base {
		key := item
		if index := strings.IndexByte(item, '='); index >= 0 {
			key = item[:index]
		}
		if key == "GIT_CONFIG" || key == "GIT_CONFIG_COUNT" || key == "GIT_CONFIG_PARAMETERS" || strings.HasPrefix(key, "GIT_CONFIG_KEY_") || strings.HasPrefix(key, "GIT_CONFIG_VALUE_") {
			continue
		}
		out = append(out, item)
	}
	out = append(out, "GIT_CONFIG_NOSYSTEM=1", "GIT_CONFIG_SYSTEM="+os.DevNull, "GIT_CONFIG_GLOBAL="+os.DevNull)
	return out
}

func neoGitCommandOK(exitCode int, stdout, stderr string) map[string]any {
	return map[string]any{"ok": true, "exitCode": exitCode, "stdout": stdout, "stderr": stderr}
}

func neoGitCommandError(code, message string) map[string]any {
	return map[string]any{"ok": false, "error": map[string]any{"code": code, "message": message}}
}

func neoTrimGitOutput(output string, maxOutputBytes int) string {
	if maxOutputBytes <= 0 || len(output) <= maxOutputBytes {
		return output
	}
	return output[:maxOutputBytes]
}

func nullableString(value string) any {
	if value == "" {
		return nil
	}
	return value
}

func numberFromString(value string) int {
	parsed, err := strconv.Atoi(strings.TrimSpace(value))
	if err != nil {
		return 0
	}
	return parsed
}

func firstN(value string, n int) string {
	if len(value) <= n {
		return value
	}
	return value[:n]
}

func (a *neoActor) upsertNotificationSubscription(msg map[string]any) {
	subscription := cloneMap(mapValue(msg["subscription"]))
	if len(subscription) == 0 {
		subscription = cloneMap(msg)
		delete(subscription, "type")
	}
	id := firstNonEmptyString(subscription["id"], subscription["subscriptionId"], msg["subscriptionId"], msg["requestId"], "default")
	a.mu.Lock()
	if a.notificationSubs == nil {
		a.notificationSubs = map[string]map[string]any{}
	}
	a.notificationSubs[id] = subscription
	a.mu.Unlock()
}

func normalizeNeoClientNotificationSubscription(msg map[string]any) (map[string]any, bool) {
	subscription, ok := asMap(msg["subscription"])
	if !ok {
		return nil, false
	}
	endpoint, ok := subscription["endpoint"].(string)
	if !ok || !validNeoURL(endpoint) {
		return nil, false
	}
	keys, ok := asMap(subscription["keys"])
	if !ok {
		return nil, false
	}
	auth, ok := neoRequiredString(keys["auth"])
	if !ok {
		return nil, false
	}
	p256dh, ok := neoRequiredString(keys["p256dh"])
	if !ok {
		return nil, false
	}
	threadURL, ok := neoRequiredString(msg["threadURL"])
	if !ok {
		return nil, false
	}
	return map[string]any{
		"type":      "client_upsert_notification_subscription",
		"threadURL": threadURL,
		"subscription": map[string]any{
			"endpoint": endpoint,
			"keys":     map[string]any{"auth": auth, "p256dh": p256dh},
		},
	}, true
}

func validNeoURL(raw string) bool {
	parsed, err := url.Parse(raw)
	return err == nil && parsed.Scheme != "" && parsed.Host != ""
}

func (rt *neoRuntime) neoWebLocalInternalRPCResponse(method string, params map[string]any) (map[string]any, int, bool) {
	if rt == nil || rt.store == nil {
		return nil, 0, false
	}
	threadID := neoInternalRPCThreadID(params)
	actor := rt.neoWebLocalInternalRPCActor(threadID)
	if actor == nil {
		return nil, 0, false
	}
	return actor.neoLocalInternalRPCResponse(method, params)
}

func (rt *neoRuntime) neoWebLocalInternalRPCActor(threadID string) *neoActor {
	if rt == nil || rt.store == nil || !neoThreadIDExactPattern.MatchString(threadID) {
		return nil
	}
	actor := rt.store.lookupThreadActor(threadID)
	if actor == nil || !actor.hasLocalThreadBootstrapState() {
		return nil
	}
	return actor
}

// archiving tracks the official top-level archived flag separately from
// thread_status, whose websocket schema only allows merging/merged/null.
func (a *neoActor) archiveThread(archive bool, _ map[string]any) {
	a.mu.Lock()
	a.archived = archive
	a.mu.Unlock()
	if a.runtime != nil && a.runtime.store != nil {
		a.runtime.store.broadcastThreadStatusUpdated(a)
	}
	a.syncCloudAsync()
	a.dispatchNotification("thread", "thread_archived", map[string]any{"archived": archive})
}

func (a *neoActor) neoLocalInternalRPCResponse(method string, params map[string]any) (map[string]any, int, bool) {
	switch strings.ToLower(strings.TrimSpace(method)) {
	case "getthreadlabels":
		return map[string]any{"ok": true, "result": neoThreadLabelObjects(a.threadLabels())}, http.StatusOK, true
	case "setthreadlabels":
		labels := a.setThreadLabels(neoThreadLabelsFromAny(params["labels"]))
		return map[string]any{"ok": true, "result": neoThreadLabelObjects(labels)}, http.StatusOK, true
	case "addthreadlabels":
		labels := a.addThreadLabels(neoThreadLabelsFromAny(params["labels"]))
		return map[string]any{"ok": true, "result": neoThreadLabelObjects(labels)}, http.StatusOK, true
	case "archivethread":
		archive := boolValue(params["archived"])
		a.archiveThread(archive, nil)
		return map[string]any{"ok": true, "result": map[string]any{"thread": a.threadID, "archived": archive}}, http.StatusOK, true
	default:
		return nil, 0, false
	}
}

func (a *neoActor) threadLabels() []string {
	if a == nil {
		return nil
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	return neoThreadLabelsFromAny(a.meta["labels"])
}

func (a *neoActor) setThreadLabels(labels []string) []string {
	if a == nil {
		return nil
	}
	a.mu.Lock()
	if a.meta == nil {
		a.meta = map[string]any{}
	}
	labels = neoNormalizeThreadLabels(labels)
	if len(labels) == 0 {
		delete(a.meta, "labels")
	} else {
		a.meta["labels"] = labels
	}
	a.mu.Unlock()
	a.syncCloudAsync()
	return labels
}

func (a *neoActor) addThreadLabels(labels []string) []string {
	if a == nil {
		return nil
	}
	a.mu.Lock()
	if a.meta == nil {
		a.meta = map[string]any{}
	}
	existing := neoThreadLabelsFromAny(a.meta["labels"])
	labels = neoNormalizeThreadLabels(append(existing, labels...))
	if len(labels) == 0 {
		delete(a.meta, "labels")
	} else {
		a.meta["labels"] = labels
	}
	a.mu.Unlock()
	a.syncCloudAsync()
	return labels
}

func neoThreadLabelsFromAny(raw any) []string {
	switch value := raw.(type) {
	case []string:
		return neoNormalizeThreadLabels(value)
	case []any:
		labels := make([]string, 0, len(value))
		for _, item := range value {
			if label := neoThreadLabelName(item); label != "" {
				labels = append(labels, label)
			}
		}
		return neoNormalizeThreadLabels(labels)
	case string:
		return neoNormalizeThreadLabels([]string{value})
	default:
		if label := neoThreadLabelName(value); label != "" {
			return []string{label}
		}
		return nil
	}
}

func neoThreadLabelName(raw any) string {
	if label := strings.TrimSpace(stringValue(raw)); label != "" {
		return label
	}
	item := mapValue(raw)
	return strings.TrimSpace(firstNonEmptyString(item["name"], item["label"], item["id"]))
}

func neoNormalizeThreadLabels(labels []string) []string {
	if len(labels) == 0 {
		return nil
	}
	out := make([]string, 0, len(labels))
	seen := map[string]struct{}{}
	for _, label := range labels {
		label = strings.TrimSpace(label)
		if label == "" {
			continue
		}
		key := strings.ToLower(label)
		if _, exists := seen[key]; exists {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, label)
	}
	return out
}

func neoThreadLabelObjects(labels []string) []any {
	out := make([]any, 0, len(labels))
	for _, label := range neoNormalizeThreadLabels(labels) {
		out = append(out, map[string]any{"name": label})
	}
	return out
}

// handleCreateThread acknowledges a request to create a sibling/child thread.
// The current binary removed handoff and deprecated fork commands in favor of
// thread mentions, so newly created local relationships use mention while
// legacy imports can still preserve their original relationship type.
func (a *neoActor) handleCreateThread(msg map[string]any) {
	threadID := firstNonEmptyString(msg["threadId"], msg["threadID"], msg["thread_id"])
	if threadID == "" {
		threadID = "T-" + randomUUIDLike()
	}
	if !neoThreadIDExactPattern.MatchString(threadID) {
		a.broadcast(map[string]any{"type": "error", "message": "invalid_thread_id", "threadId": threadID, "code": "INVALID_THREAD_ID"})
		return
	}
	var created *neoActor
	if a.runtime != nil && a.runtime.store != nil {
		created = a.runtime.store.ensureThreadActor(threadID)
	}
	relationshipType := neoActiveThreadRelationshipType(msg)
	createdAt := time.Now().UnixMilli()
	relationship, ok := neoProtocolThreadRelationship(threadID, relationshipType, "child", createdAt, stringValue(msg["comment"]))
	if !ok {
		return
	}
	if created != nil {
		if parentRelationship, ok := neoProtocolThreadRelationship(a.threadID, relationshipType, "parent", createdAt, stringValue(msg["comment"])); ok {
			created.mu.Lock()
			created.upsertRelationshipLocked(parentRelationship)
			created.touchLocked()
			created.mu.Unlock()
		}
	}
	payload := map[string]any{
		"type":          "thread_relationships",
		"relationships": []any{relationship},
	}
	payload["seq"] = a.recordRelationshipEvent(payload)
	a.broadcast(payload)
	if created != nil && a.runtime != nil && a.runtime.store != nil {
		a.runtime.store.broadcastThreadStatusUpdated(created)
		created.syncCloudAsync()
	}
	a.dispatchNotification("thread", "thread_created", map[string]any{"threadId": threadID, "kind": relationship["type"]})
	a.syncCloudAsync()
}

func neoActiveThreadRelationshipType(msg map[string]any) string {
	kind := firstNonEmptyString(msg["kind"], msg["relationshipType"], msg["relationship_type"], msg["type"])
	switch kind {
	case "fork":
		return "fork"
	case "mention", "client_create_thread", "create_thread", "":
		return "mention"
	default:
		return "mention"
	}
}

// handleForkThread accepts a `fork` request and emits a relationships update
// describing the parent/child link. Forking the message history is left to the
// caller via a follow-up `import` request.
func (a *neoActor) handleForkThread(msg map[string]any) {
	forkID := firstNonEmptyString(msg["threadId"], msg["forkThreadId"], msg["targetThreadId"])
	if forkID == "" {
		forkID = "T-" + randomUUIDLike()
	}
	if !neoThreadIDExactPattern.MatchString(forkID) {
		a.broadcast(map[string]any{"type": "error", "message": "invalid_thread_id", "threadId": forkID, "code": "INVALID_THREAD_ID"})
		return
	}
	var forked *neoActor
	if a.runtime != nil && a.runtime.store != nil {
		forked = a.runtime.store.ensureThreadActor(forkID)
	}
	createdAt := time.Now().UnixMilli()
	relationship, ok := neoProtocolThreadRelationship(forkID, "fork", "child", createdAt, stringValue(msg["comment"]))
	if !ok {
		return
	}
	if forkPoint := stringValue(msg["forkMessageId"]); forkPoint != "" {
		relationship["comment"] = "forked from " + forkPoint
	}
	if forked != nil {
		if parentRelationship, ok := neoProtocolThreadRelationship(a.threadID, "fork", "parent", createdAt, stringValue(relationship["comment"])); ok {
			forked.mu.Lock()
			forked.upsertRelationshipLocked(parentRelationship)
			forked.touchLocked()
			forked.mu.Unlock()
		}
	}
	payload := map[string]any{
		"type":          "thread_relationships",
		"relationships": []any{relationship},
	}
	payload["seq"] = a.recordRelationshipEvent(payload)
	a.broadcast(payload)
	if forked != nil && a.runtime != nil && a.runtime.store != nil {
		a.runtime.store.broadcastThreadStatusUpdated(forked)
		forked.syncCloudAsync()
	}
	a.dispatchNotification("thread", "thread_forked", map[string]any{"threadId": forkID, "comment": relationship["comment"]})
	a.syncCloudAsync()
}

// handleSendMessageToThread relays a synthetic user message to a sibling/child
// thread. Workflows with hidden binary modes seed the target's first queued turn;
// the source actor records only the mention relationship.
func (a *neoActor) handleSendMessageToThread(msg map[string]any) {
	targetID := firstNonEmptyString(msg["threadId"], msg["targetThreadId"])
	if !neoThreadIDExactPattern.MatchString(targetID) {
		a.broadcast(map[string]any{"type": "error", "message": "invalid_thread_id", "threadId": targetID, "code": "INVALID_THREAD_ID"})
		return
	}
	target := a.runtime.store.ensureThreadActor(targetID)
	if target == nil {
		return
	}
	workflow := neoSendMessageToThreadWorkflow(msg)
	agentMode, reasoningEffort := neoSendMessageToThreadWorkflowMode(workflow)
	payload := map[string]any{
		"type":             "client_append_user_msg",
		"messageId":        firstNonEmptyString(msg["messageId"], newNeoMessageID()),
		"content":          neoSendMessageToThreadContent(msg, targetID),
		"parentToolCallId": stringValue(msg["parentToolCallId"]),
		"sourceThreadId":   a.threadID,
	}
	if agentMode != "" {
		payload["agentMode"] = agentMode
		payload["reasoningEffort"] = reasoningEffort
		payload["steer"] = true
	}
	go target.handle(payload)
	if relationship, ok := neoProtocolThreadRelationship(targetID, "mention", "child", time.Now().UnixMilli(), stringValue(msg["comment"])); ok {
		relationshipPayload := map[string]any{"type": "thread_relationships", "relationships": []any{relationship}}
		relationshipPayload["seq"] = a.recordRelationshipEvent(relationshipPayload)
		a.broadcast(relationshipPayload)
		a.syncCloudAsync()
	}
}

func neoSendMessageToThreadContent(msg map[string]any, targetID string) any {
	if neoMessageContentPresent(msg["content"]) {
		return msg["content"]
	}
	if prompt := neoSendMessageToThreadWorkflowPrompt(neoSendMessageToThreadWorkflow(msg), targetID); prompt != "" {
		return []any{map[string]any{"type": "text", "text": prompt}}
	}
	return msg["content"]
}

func neoMessageContentPresent(value any) bool {
	switch typed := value.(type) {
	case nil:
		return false
	case string:
		return strings.TrimSpace(typed) != ""
	case []any:
		return len(typed) > 0
	}
	if m, ok := asMap(value); ok {
		return len(m) > 0
	}
	return true
}

func neoSendMessageToThreadWorkflow(msg map[string]any) string {
	return firstNonEmptyString(
		msg["workflow"],
		nestedValue(msg["input"], "workflow"),
		nestedValue(msg["arguments"], "workflow"),
		nestedValue(msg["args"], "workflow"),
	)
}

func neoSendMessageToThreadWorkflowMode(workflow string) (string, string) {
	// Only workflows backed by hidden binary modes should switch the target thread.
	// merge_changes stays mode-neutral because it supplies prompt content only.
	switch strings.ToLower(strings.TrimSpace(workflow)) {
	case "code_review":
		return "review", defaultNeoReasoningEffort("review")
	default:
		return "", ""
	}
}

func neoSendMessageToThreadWorkflowPrompt(workflow, targetID string) string {
	switch strings.ToLower(strings.TrimSpace(workflow)) {
	case "code_review":
		return neoCanonicalCodeReviewPrompt()
	case "merge_changes":
		return neoCanonicalMergeChangesPrompt(targetID)
	default:
		return ""
	}
}

// The send_message_to_thread workflows live server-side in Amp (the gaac893
// binary no longer carries them), so they are frozen here together with the
// aggman prompt that instructs them; the pair must stay coherent.
func neoCanonicalCodeReviewPrompt() string {
	return "Review the changes with the code review tool."
}

func neoCanonicalMergeChangesPrompt(threadID string) string {
	threadID = strings.TrimSpace(threadID)
	if threadID == "" {
		threadID = "<thread-id>"
	}
	return strings.Join([]string{
		"Commit and merge the changes to a single commit on origin/main.",
		"Run the full test suite before pushing.",
		"If there's a non-trivial merge conflict, resolve it and confirm with me before pushing.",
		"After resolving any merge conflict, ensure the changes are properly formatted before committing and pushing.",
		"If test failures are unrelated to this change (due to a commit upstream that introduced the failure), they can be ignored.",
		"After the merge succeeds, run `amp threads archive " + threadID + "` to archive this thread.",
	}, " ")
}

// handleSendMessageToAggman is a stub for the aggregator manager flow used in
// deep mode. Without a real aggman binding we acknowledge it locally and emit
// a notification so observers know the message was accepted.
func (a *neoActor) handleSendMessageToAggman(msg map[string]any) {
	a.broadcast(map[string]any{
		"type":      "plugin_message",
		"message":   map[string]any{"target": "aggman", "payload": msg["payload"]},
		"messageId": firstNonEmptyString(msg["messageId"], newNeoMessageID()),
	})
	a.dispatchNotification("aggman", "message_sent", map[string]any{"payload": msg["payload"]})
}

// bumpSeqAndRemember allocates a new seq, records a replay event with that
// seq, and returns it. Callers can use the returned seq when broadcasting.
func (a *neoActor) bumpSeqAndRemember(payload map[string]any) int {
	a.mu.Lock()
	seq := a.nextSeqLocked()
	if payload != nil {
		clone := cloneMap(payload)
		clone["seq"] = seq
		a.rememberReplayEventLocked(clone)
	}
	a.mu.Unlock()
	return seq
}

func (a *neoActor) recordRelationshipEvent(payload map[string]any) int {
	a.mu.Lock()
	for _, raw := range arrayValue(payload["relationships"]) {
		a.upsertRelationshipLocked(mapValue(raw))
	}
	seq := a.nextSeqLocked()
	clone := cloneMap(payload)
	relationships := a.protocolRelationshipListLocked()
	clone["relationships"] = relationships
	clone["seq"] = seq
	a.rememberReplayEventLocked(clone)
	payload["relationships"] = relationships
	a.mu.Unlock()
	return seq
}

// dispatchNotification is a no-op placeholder. The Amp binary's notification
// system uses Web Push (subscription.endpoint + VAPID keys) delivered out of
// band, not WebSocket frames. We retain the subscription map so future
// integrations can deliver real pushes, but emitting synthetic `notification`
// frames here would not be parsed by the IDE's zod schemas. The argument
// signature is preserved so call sites do not need changes.
func (a *neoActor) dispatchNotification(category, event string, payload map[string]any) {
	a.mu.Lock()
	hasSubs := len(a.notificationSubs) > 0
	a.mu.Unlock()
	if !hasSubs {
		return
	}
	log.Debugf("amp neo notification (no-op): category=%s event=%s threadId=%s", category, event, a.threadID)
}

func (a *neoActor) broadcastObservers() {
	a.mu.Lock()
	count := len(a.sockets)
	hasExecutor := a.executorConnectedLocked()
	a.mu.Unlock()
	a.broadcast(neoObserversPayload(count, hasExecutor))
}

func neoObserversPayload(count int, hasExecutor bool) map[string]any {
	return map[string]any{"type": "observers", "count": count, "observers": []any{}, "hasExecutor": hasExecutor}
}

func (a *neoActor) broadcast(payload any) {
	a.maybeBroadcastThreadStatusUpdated(payload)
	for _, socket := range a.socketList() {
		if socket == nil || socket.conn == nil {
			continue
		}
		socket.send(payload)
	}
}

func (a *neoActor) routeTerminalBridge(source *neoSocket, msg map[string]any, bridgedType string) {
	payload := neoRetypedMessage(msg, bridgedType)
	msgType := stringValue(msg["type"])
	if strings.HasPrefix(msgType, "client_terminal_") {
		a.mu.Lock()
		executorSocket := a.executorSocket
		a.mu.Unlock()
		if executorSocket != nil {
			executorSocket.send(payload)
		}
		return
	}
	if strings.HasPrefix(msgType, "executor_terminal_") {
		a.mu.Lock()
		executorSocket := a.executorSocket
		a.mu.Unlock()
		if source != nil && executorSocket != nil && source != executorSocket {
			return
		}
		for _, socket := range a.socketList() {
			if socket == source || socket.isExecutor() {
				continue
			}
			socket.send(payload)
		}
	}
}

func (a *neoActor) maybeBroadcastThreadStatusUpdated(payload any) {
	if a == nil || a.runtime == nil || a.runtime.store == nil || !neoGatewayThreadActorTarget(a.name) {
		return
	}
	msg := mapValue(payload)
	switch stringValue(msg["type"]) {
	case "agent_state", "executor_connected", "thread_relationships", "thread_status", "thread_title":
		a.runtime.store.broadcastThreadStatusUpdated(a)
	}
}

func (a *neoActor) socketList() []*neoSocket {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.socketListLocked()
}

func (a *neoActor) socketListLocked() []*neoSocket {
	sockets := make([]*neoSocket, 0, len(a.sockets))
	for socket := range a.sockets {
		sockets = append(sockets, socket)
	}
	return sockets
}

func (a *neoActor) spawnedExecutorListLocked() []*neoSpawnedExecutor {
	executors := make([]*neoSpawnedExecutor, 0, len(a.spawnedExecutors))
	for _, executor := range a.spawnedExecutors {
		if executor != nil {
			executors = append(executors, executor)
		}
	}
	return executors
}

func (a *neoActor) spawnedExecutorStatusListLocked() []any {
	if len(a.spawnedExecutors) == 0 {
		return []any{}
	}
	spawnIDs := make([]string, 0, len(a.spawnedExecutors))
	for spawnID := range a.spawnedExecutors {
		spawnIDs = append(spawnIDs, spawnID)
	}
	sort.Strings(spawnIDs)
	statuses := make([]any, 0, len(spawnIDs))
	for _, spawnID := range spawnIDs {
		spawned := a.spawnedExecutors[spawnID]
		if spawned == nil || spawned.stopping {
			continue
		}
		statuses = append(statuses, normalizeNeoExecutorStatus(map[string]any{
			"type":    "executor_status",
			"spawnId": spawnID,
			"status":  "running",
			"message": "Waiting for local Amp headless executor to connect.",
			"details": map[string]any{
				"reasonCode": "waiting_for_executor_connect",
				"threadId":   spawned.threadID,
				"pid":        spawned.pid(),
				"logFile":    omitEmpty(spawned.logPath),
				"startedAt":  spawned.startedAt.UTC().Format(time.RFC3339Nano),
			},
		}))
	}
	return statuses
}

func (a *neoActor) artifactListLocked() []any {
	if len(a.artifacts) == 0 {
		return []any{}
	}
	keys := make([]string, 0, len(a.artifacts))
	for key := range a.artifacts {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	artifacts := make([]any, 0, len(keys))
	for _, key := range keys {
		artifacts = append(artifacts, normalizeNeoArtifact(a.artifacts[key], ""))
	}
	return artifacts
}

func (a *neoActor) relationshipListLocked() []any {
	if len(a.relationships) == 0 {
		return []any{}
	}
	relationships := make([]any, 0, len(a.relationships))
	for _, relationship := range a.relationships {
		relationships = append(relationships, cloneMap(relationship))
	}
	return relationships
}

func (a *neoActor) protocolRelationshipListLocked() []any {
	return neoProtocolThreadRelationshipList(a.relationshipListLocked())
}

func (a *neoActor) threadRelationshipsLocked(messages []neoMessage) []any {
	return neoMergeThreadRelationshipsWithExplicit(neoThreadRelationships(messages), a.relationshipListLocked())
}

func (a *neoActor) threadProtocolRelationshipsLocked(messages []neoMessage) []any {
	return neoProtocolThreadRelationshipList(neoMergeThreadRelationshipsWithExplicit(neoThreadRelationships(messages), a.relationshipListLocked()))
}

func (a *neoActor) upsertRelationshipLocked(relationship map[string]any) {
	normalized, ok := normalizeNeoThreadRelationship(relationship)
	if !ok {
		return
	}
	key := neoThreadRelationshipKey(normalized)
	for i, existing := range a.relationships {
		if neoThreadRelationshipKey(existing) == key {
			a.relationships[i] = normalized
			return
		}
	}
	a.relationships = append(a.relationships, normalized)
}

func (a *neoActor) filterRelationshipsForTruncationLocked(fromIndex int) {
	if len(a.relationships) == 0 || fromIndex < 0 {
		return
	}
	filtered := a.relationships[:0]
	for _, relationship := range a.relationships {
		messageIndex, hasMessageIndex := relationship["messageIndex"]
		if hasMessageIndex && numberFrom(messageIndex) >= fromIndex {
			continue
		}
		filtered = append(filtered, relationship)
	}
	a.relationships = filtered
}

func (a *neoActor) upsertCompactionRecordLocked(record map[string]any) {
	cutMessageID := stringValue(record["cutMessageId"])
	if cutMessageID == "" {
		return
	}
	for i, existing := range a.compactionRecords {
		if stringValue(existing["cutMessageId"]) == cutMessageID {
			a.compactionRecords[i] = cloneMap(record)
			return
		}
	}
	a.compactionRecords = append(a.compactionRecords, cloneMap(record))
}

func (a *neoActor) compactionRecordListLocked() []any {
	if len(a.compactionRecords) == 0 {
		return []any{}
	}
	records := make([]any, 0, len(a.compactionRecords))
	for _, record := range a.compactionRecords {
		records = append(records, cloneMap(record))
	}
	return records
}

func neoRestoredApprovalQueue(messages []neoMessage) []map[string]any {
	type restoredToolUse struct {
		Name             string
		Input            map[string]any
		ParentToolCallID string
	}

	toolUses := map[string]restoredToolUse{}
	for _, message := range messages {
		if message.Role != "assistant" {
			continue
		}
		for _, rawBlock := range message.Content {
			block := mapValue(rawBlock)
			if stringValue(block["type"]) != "tool_use" {
				continue
			}
			toolCallID := firstNonEmptyString(block["id"], block["toolUseID"], block["tool_use_id"], block["toolCallId"])
			toolName := stringValue(block["name"])
			if toolCallID == "" || toolName == "" {
				continue
			}
			toolUses[toolCallID] = restoredToolUse{
				Name:             toolName,
				Input:            mapValue(block["input"]),
				ParentToolCallID: firstNonEmptyString(block["parentToolCallId"], block["parentToolUseId"], message.ParentToolUseID),
			}
		}
	}

	approvals := make([]map[string]any, 0)
	seen := map[string]bool{}
	fallbackTimestamp := int(time.Now().UnixMilli())
	for _, message := range messages {
		if message.Role != "user" {
			continue
		}
		for _, rawBlock := range message.Content {
			block := mapValue(rawBlock)
			if stringValue(block["type"]) != "tool_result" {
				continue
			}
			run := mapValue(block["run"])
			if strings.ToLower(strings.TrimSpace(stringValue(run["status"]))) != "blocked-on-user" {
				continue
			}
			toolCallID := firstNonEmptyString(block["toolUseID"], block["toolUseId"], block["tool_use_id"], block["toolCallId"])
			if toolCallID == "" || seen[toolCallID] {
				continue
			}
			seen[toolCallID] = true
			toolUse := toolUses[toolCallID]
			toolName := firstNonEmptyString(block["toolName"], run["toolName"], toolUse.Name)
			if toolName == "" {
				toolName = "unknown"
			}
			args := firstMap(block["args"], run["args"], toolUse.Input)
			parentToolCallID := firstNonEmptyString(block["parentToolCallId"], block["parentToolUseId"], run["parentToolCallId"], run["parentToolUseId"], message.ParentToolUseID, toolUse.ParentToolCallID)
			contextValue := stringValue(firstNonNil(block["context"], run["context"]))
			if contextValue != "thread" && contextValue != "subagent" {
				if parentToolCallID != "" {
					contextValue = "subagent"
				} else {
					contextValue = "thread"
				}
			}
			timestamp := numberFrom(block["timestamp"], run["timestamp"])
			if timestamp <= 0 {
				timestamp = fallbackTimestamp
			}
			approval := map[string]any{
				"id":         fallbackString(block["id"], toolCallID),
				"toolCallId": toolCallID,
				"toolName":   toolName,
				"args":       cloneMap(args),
				"context":    contextValue,
				"timestamp":  timestamp,
			}
			if reason := firstNonEmptyString(block["reason"], run["reason"]); reason != "" {
				approval["reason"] = reason
			}
			if toAllow := stringArrayValue(firstNonNil(block["toAllow"], run["toAllow"])); len(toAllow) > 0 {
				approval["toAllow"] = toAllow
			}
			if subagentToolName := firstNonEmptyString(block["subagentToolName"], run["subagentToolName"]); subagentToolName != "" {
				approval["subagentToolName"] = subagentToolName
			}
			if parentToolCallID != "" {
				approval["parentToolCallId"] = parentToolCallID
			}
			if matchedRule := mapValue(firstNonNil(block["matchedRule"], run["matchedRule"])); len(matchedRule) > 0 {
				approval["matchedRule"] = cloneMap(matchedRule)
			}
			if ruleSource := stringValue(firstNonNil(block["ruleSource"], run["ruleSource"])); ruleSource == "user" || ruleSource == "built-in" {
				approval["ruleSource"] = ruleSource
			}
			approvals = append(approvals, approval)
		}
	}
	return approvals
}

func neoRestoredPendingTools(messages []neoMessage, agentMode, reasoningEffort string) map[string]neoPendingTool {
	pending := map[string]neoPendingTool{}
	for _, message := range messages {
		switch message.Role {
		case "assistant":
			messageMode := firstNonEmptyString(message.AgentMode, agentMode)
			messageEffort := firstNonEmptyString(message.ReasoningEffort, reasoningEffort)
			if !neoReasoningEffortAllowedForMode(messageMode, messageEffort) {
				messageEffort = defaultNeoReasoningEffort(messageMode)
			}
			for _, rawBlock := range message.Content {
				block := mapValue(rawBlock)
				if stringValue(block["type"]) != "tool_use" {
					continue
				}
				toolCallID := firstNonEmptyString(block["id"], block["toolUseID"], block["tool_use_id"], block["toolCallId"])
				toolName := normalizeNeoToolCallName(stringValue(block["name"]))
				if toolCallID == "" || toolName == "" || boolValue(block["inputIncomplete"]) {
					continue
				}
				pending[toolCallID] = neoPendingTool{
					ID:               toolCallID,
					Name:             toolName,
					Input:            normalizeNeoToolCallInput(toolName, mapValue(block["input"])),
					AgentMode:        messageMode,
					ReasoningEffort:  messageEffort,
					MessageID:        message.MessageID,
					ParentToolCallID: firstNonEmptyString(block["parentToolCallId"], block["parentToolUseId"], message.ParentToolUseID),
				}
			}
		case "user":
			for _, rawBlock := range message.Content {
				block := mapValue(rawBlock)
				if stringValue(block["type"]) != "tool_result" {
					continue
				}
				toolCallID := firstNonEmptyString(block["toolUseID"], block["toolUseId"], block["tool_use_id"], block["toolCallId"])
				if toolCallID == "" {
					continue
				}
				tool, ok := pending[toolCallID]
				if ok && neoToolRunTerminalForPending(tool, mapValue(block["run"])) {
					delete(pending, toolCallID)
				}
			}
		}
	}
	return pending
}

func neoNormalizeImportedToolProgressMessages(messages []neoMessage) []neoMessage {
	if len(messages) == 0 {
		return messages
	}
	normalized := make([]neoMessage, len(messages))
	copy(normalized, messages)
	toolNames := map[string]string{}
	for i := range normalized {
		message := normalized[i]
		switch message.Role {
		case "assistant":
			for _, rawBlock := range message.Content {
				block := mapValue(rawBlock)
				if stringValue(block["type"]) != "tool_use" {
					continue
				}
				toolCallID := firstNonEmptyString(block["id"], block["toolUseID"], block["tool_use_id"], block["toolCallId"])
				toolName := stringValue(block["name"])
				if toolCallID != "" && toolName != "" {
					toolNames[toolCallID] = normalizeNeoToolCallName(toolName)
				}
			}
		case "user":
			if status, ok := neoToolResultMessageCompletionStatusWithToolNames(message.Content, toolNames); ok {
				message.CompletionStatus = status
				normalized[i] = message
			}
		}
	}
	return normalized
}

func (a *neoActor) cancelToolResultMessagesLocked(toolCallIDs []string, reason string) []map[string]any {
	if len(toolCallIDs) == 0 || len(a.messages) == 0 {
		return nil
	}
	ids := make(map[string]struct{}, len(toolCallIDs))
	for _, toolCallID := range toolCallIDs {
		if toolCallID != "" {
			ids[toolCallID] = struct{}{}
		}
	}
	if len(ids) == 0 {
		return nil
	}

	updates := make([]map[string]any, 0)
	matched := make(map[string]bool, len(ids))
	for i, message := range a.messages {
		if message.Role != "user" || len(message.Content) == 0 {
			continue
		}
		content := make([]any, len(message.Content))
		changed := false
		for blockIndex, rawBlock := range message.Content {
			block, ok := asMap(rawBlock)
			if !ok {
				content[blockIndex] = rawBlock
				continue
			}
			clonedBlock := cloneMap(block)
			if stringValue(clonedBlock["type"]) != "tool_result" {
				content[blockIndex] = clonedBlock
				continue
			}
			toolCallID := firstNonEmptyString(clonedBlock["toolUseID"], clonedBlock["toolUseId"], clonedBlock["tool_use_id"], clonedBlock["toolCallId"])
			if _, ok := ids[toolCallID]; !ok {
				content[blockIndex] = clonedBlock
				continue
			}
			matched[toolCallID] = true
			run := cloneMap(mapValue(clonedBlock["run"]))
			if neoToolRunTerminal(run) {
				content[blockIndex] = clonedBlock
				continue
			}
			run["status"] = "cancelled"
			if reason != "" {
				run["reason"] = reason
			}
			clonedBlock["run"] = run
			content[blockIndex] = clonedBlock
			changed = true
		}
		if !changed {
			continue
		}
		message.Content = content
		message.CompletionStatus = ""
		a.messages[i] = message
		seq := a.nextSeqLocked()
		event := map[string]any{"type": "message_updated", "message": message.protocol(), "seq": seq}
		a.rememberReplayEventLocked(event)
		updates = append(updates, event)
	}
	for _, toolCallID := range toolCallIDs {
		if toolCallID == "" || matched[toolCallID] {
			continue
		}
		matched[toolCallID] = true
		ref, ok := a.storedToolUseLocked(toolCallID)
		if !ok {
			continue
		}
		run := map[string]any{"status": "cancelled"}
		if reason != "" {
			run["reason"] = reason
		}
		_, event := a.storeToolResultEventLocked(ref, map[string]any{"type": "tool_result", "toolUseID": toolCallID, "run": run}, "")
		updates = append(updates, event)
	}
	if len(updates) > 0 {
		a.rebuildHistoryLocked()
	}
	return updates
}

func neoCancelledToolRunReason(leaseReason string) string {
	switch leaseReason {
	case "executor_disconnected", "reassigned":
		return "system:disposed"
	default:
		return "user:cancelled"
	}
}

func (a *neoActor) normalizeToolApprovalRequestLocked(msg map[string]any) (map[string]any, bool) {
	raw := cloneMap(mapValue(msg["approval"]))
	if len(raw) == 0 {
		raw = cloneMap(msg)
		delete(raw, "type")
		delete(raw, "approval")
	}
	toolCallID := firstNonEmptyString(raw["toolCallId"], raw["toolUseId"], raw["toolUseID"], raw["tool_use_id"], msg["toolCallId"], msg["toolUseId"], msg["toolUseID"], msg["tool_use_id"])
	if toolCallID == "" {
		return nil, false
	}
	pending := a.pendingTools[toolCallID]
	toolName := firstNonEmptyString(raw["toolName"], raw["name"], msg["toolName"], msg["name"], pending.Name)
	if toolName == "" {
		toolName = "unknown"
	}
	args := firstMap(raw["args"], raw["input"], msg["args"], msg["input"], pending.Input)
	contextValue := stringValue(raw["context"])
	parentToolCallID := firstNonEmptyString(raw["parentToolCallId"], raw["parentToolUseId"], raw["parent_tool_use_id"], msg["parentToolCallId"], msg["parentToolUseId"], pending.ParentToolCallID)
	subagentToolName := firstNonEmptyString(raw["subagentToolName"], raw["subagentName"], msg["subagentToolName"], msg["subagentName"])
	if contextValue != "thread" && contextValue != "subagent" {
		if parentToolCallID != "" || subagentToolName != "" {
			contextValue = "subagent"
		} else {
			contextValue = "thread"
		}
	}
	timestamp := numberFrom(raw["timestamp"], msg["timestamp"])
	if timestamp <= 0 {
		timestamp = int(time.Now().UnixMilli())
	}
	approval := map[string]any{
		"id":         fallbackString(raw["id"], toolCallID),
		"toolCallId": toolCallID,
		"toolName":   toolName,
		"args":       cloneMap(args),
		"context":    contextValue,
		"timestamp":  timestamp,
	}
	if reason := firstNonEmptyString(raw["reason"], msg["reason"]); reason != "" {
		approval["reason"] = reason
	}
	if toAllow := stringArrayValue(firstNonNil(raw["toAllow"], msg["toAllow"])); len(toAllow) > 0 {
		approval["toAllow"] = toAllow
	}
	if subagentToolName != "" {
		approval["subagentToolName"] = subagentToolName
	}
	if parentToolCallID != "" {
		approval["parentToolCallId"] = parentToolCallID
	}
	if matchedRule := mapValue(firstNonNil(raw["matchedRule"], msg["matchedRule"])); len(matchedRule) > 0 {
		approval["matchedRule"] = cloneMap(matchedRule)
	}
	if ruleSource := stringValue(firstNonNil(raw["ruleSource"], msg["ruleSource"])); ruleSource == "user" || ruleSource == "built-in" {
		approval["ruleSource"] = ruleSource
	}
	return approval, true
}

func (a *neoActor) upsertApprovalLocked(approval map[string]any) {
	key := neoApprovalKey(approval)
	if key == "" {
		return
	}
	for i, existing := range a.approvalQueue {
		if neoApprovalKey(existing) == key {
			a.approvalQueue[i] = neoProtocolApproval(approval)
			return
		}
	}
	a.approvalQueue = append(a.approvalQueue, neoProtocolApproval(approval))
}

func (a *neoActor) removeApprovalLocked(toolCallID string) bool {
	if toolCallID == "" || len(a.approvalQueue) == 0 {
		return false
	}
	removed := false
	filtered := a.approvalQueue[:0]
	for _, approval := range a.approvalQueue {
		key := neoApprovalKey(approval)
		if key == toolCallID || stringValue(approval["id"]) == toolCallID {
			removed = true
			continue
		}
		filtered = append(filtered, approval)
	}
	if removed {
		a.approvalQueue = filtered
	}
	return removed
}

func (a *neoActor) approvalQueueListLocked() []any {
	if len(a.approvalQueue) == 0 {
		return []any{}
	}
	approvals := make([]any, 0, len(a.approvalQueue))
	for _, approval := range a.approvalQueue {
		approvals = append(approvals, neoProtocolApproval(approval))
	}
	return approvals
}

func (a *neoActor) threadQueuedMessageListLocked() []any {
	if len(a.queue) == 0 {
		return []any{}
	}
	messages := make([]any, 0, len(a.queue))
	for _, item := range a.queue {
		if item.MessageID == "" {
			continue
		}
		messages = append(messages, map[string]any{
			"id":            item.queueID(),
			"queuedMessage": item.threadProtocol(),
		})
	}
	return messages
}

func (a *neoActor) queuedMessageProtocolListLocked() []any {
	if len(a.queue) == 0 {
		return []any{}
	}
	messages := make([]any, 0, len(a.queue))
	for _, item := range a.queue {
		if item.MessageID == "" {
			continue
		}
		messages = append(messages, item.queueProtocol())
	}
	return messages
}

func (a *neoActor) storeMessage(message neoMessage) neoMessage {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.storeMessageLocked(message)
}

func (a *neoActor) storeMessageLocked(message neoMessage) neoMessage {
	for i, existing := range a.messages {
		if existing.MessageID == message.MessageID {
			if message.Seq <= 0 {
				message.Seq = existing.Seq
			} else if message.Seq >= a.seq {
				a.seq = message.Seq + 1
			}
			a.messages[i] = message
			return message
		}
	}
	if message.Seq <= 0 {
		message.Seq = a.nextSeqLocked()
	} else if message.Seq >= a.seq {
		a.seq = message.Seq + 1
	}
	a.messages = append(a.messages, message)
	return message
}

func (a *neoActor) storeMessageEventLocked(message neoMessage) (neoMessage, map[string]any) {
	for i, existing := range a.messages {
		if existing.MessageID != message.MessageID {
			continue
		}
		if message.CreatedAt == "" {
			message.CreatedAt = existing.CreatedAt
		}
		if message.ParentToolUseID == "" {
			message.ParentToolUseID = existing.ParentToolUseID
		}
		message.Seq = existing.Seq
		a.messages[i] = message
		seq := a.nextSeqLocked()
		event := map[string]any{"type": "message_updated", "message": message.protocol(), "seq": seq}
		a.rememberReplayEventLocked(event)
		return message, event
	}
	stored := a.storeMessageLocked(message)
	return stored, neoMessageAddedPayload(stored)
}

func (a *neoActor) toolResultRunLocked(toolCallID string) (map[string]any, any) {
	for _, message := range a.messages {
		if message.Role != "user" {
			continue
		}
		for _, raw := range message.Content {
			block := mapValue(raw)
			if stringValue(block["type"]) != "tool_result" {
				continue
			}
			if firstNonEmptyString(block["toolUseID"], block["tool_use_id"], block["toolCallId"]) != toolCallID {
				continue
			}
			return cloneMap(mapValue(block["run"])), block["userInput"]
		}
	}
	return nil, nil
}

func (a *neoActor) rebuildHistoryLocked() {
	a.history = neoHistoryFromStoredMessages(a.messages, a.compactionRecords)
}

func neoHistoryFromStoredMessages(messages []neoMessage, records []map[string]any) []neoHistoryMessage {
	toolNames := map[string]string{}
	// Honor compaction: the binary's provider runner replaces compacted
	// history with a user-role summary payload, then continues from the cut
	// boundary. Otherwise, use the latest compaction record cut message as
	// the boundary, matching the binary transcript rebuild.
	recordIndex, recordOK := neoLatestCompactionRecordMessageIndex(messages, records)
	if cutIndex, summaryText, ok := neoCompactionSummary(messages); ok && (!recordOK || recordIndex <= cutIndex+1) {
		history := make([]neoHistoryMessage, 0, len(messages)-cutIndex+1)
		history = append(history, neoCompactionSummaryHistoryMessage(summaryText))
		for _, message := range messages[cutIndex+1:] {
			history = append(history, neoHistoryMessageFromStored(message, toolNames)...)
		}
		return history
	}
	start := 0
	if recordOK {
		start = recordIndex
	}
	history := make([]neoHistoryMessage, 0, len(messages)-start)
	for _, message := range messages[start:] {
		history = append(history, neoHistoryMessageFromStored(message, toolNames)...)
	}
	return history
}

// neoCompactionSummary returns the index of the most recent info message that
// holds a summary block plus the rendered summary text. when present, history
// before that message must be dropped and the summary becomes the prefix.
func neoCompactionSummary(messages []neoMessage) (int, string, bool) {
	for i := len(messages) - 1; i >= 0; i-- {
		message := messages[i]
		if message.Role != "info" {
			continue
		}
		for _, raw := range message.Content {
			block := mapValue(raw)
			if stringValue(block["type"]) != "summary" {
				continue
			}
			text := neoCompactionSummaryText(mapValue(block["summary"]))
			if text == "" {
				continue
			}
			return i, text, true
		}
	}
	return 0, "", false
}

func neoCompactionSummaryText(summary map[string]any) string {
	switch stringValue(summary["type"]) {
	case "message":
		return strings.TrimSpace(stringValue(summary["summary"]))
	case "thread":
		threadID := strings.TrimSpace(stringValue(summary["thread"]))
		if threadID != "" {
			return "Summary thread: " + threadID
		}
	}
	return ""
}

func neoCompactionSummaryHistoryMessage(summaryText string) neoHistoryMessage {
	return neoHistoryMessage{Role: "user", Text: summaryText}
}

// neoHistoryMessageFromStored converts a stored neoMessage into the inference
// history representation used by the per-provider message builders.
func neoHistoryMessageFromStored(message neoMessage, toolNames map[string]string) []neoHistoryMessage {
	switch message.Role {
	case "assistant":
		text, calls, thinkingBlocks := neoAssistantHistoryContent(message.Content)
		for _, call := range calls {
			toolNames[call.ID] = call.Name
		}
		return []neoHistoryMessage{{Role: "assistant", Text: text, ToolCalls: calls, ThinkingBlocks: thinkingBlocks, ParentToolUseID: message.ParentToolUseID}}
	case "user":
		if message.CompletionStatus == "tool_progress" {
			return nil
		}
		if toolResults := neoToolResultHistoryContent(message.Content, toolNames, message.ParentToolUseID); len(toolResults) > 0 {
			return toolResults
		}
		text := neoUserHistoryText(message.Content, message.UserState, message.FileMentions)
		if message.Interrupted && text != "" {
			text = "*(interrupted)*\n" + text
		}
		content := neoUserHistoryContent(message.Content, message.UserState, message.FileMentions)
		if message.Interrupted && len(content) > 0 {
			first := cloneMap(mapValue(content[0]))
			if stringValue(first["type"]) == "text" {
				first["text"] = "*(interrupted)*\n" + stringValue(first["text"])
				content[0] = first
			}
		}
		return []neoHistoryMessage{{Role: "user", Text: text, Content: content, ParentToolUseID: message.ParentToolUseID, UserState: message.UserState}}
	case "info":
		return neoInfoHistoryContent(message.Content, message.ParentToolUseID)
	}
	return nil
}

func (a *neoActor) nextSeqLocked() int {
	seq := a.seq
	a.seq++
	return seq
}

func (a *neoActor) lastSeqLocked() int {
	last := a.seq - 1
	if last < 1 {
		last = 1
	}
	for _, message := range a.messages {
		if message.Seq > last {
			last = message.Seq
		}
	}
	for _, event := range a.replayEvents {
		if event.Seq > last {
			last = event.Seq
		}
	}
	if a.activeErrorSeq > last {
		last = a.activeErrorSeq
	}
	return last
}

func (a *neoActor) rememberReplayEventLocked(payload map[string]any) {
	seq := numberFrom(payload["seq"])
	if seq <= 0 {
		return
	}
	a.replayEvents = append(a.replayEvents, neoReplayEvent{Seq: seq, Payload: cloneNeoProtocolPayload(payload)})
	if overflow := len(a.replayEvents) - neoReplayEventLimit; overflow > 0 {
		a.replayEvents = append([]neoReplayEvent(nil), a.replayEvents[overflow:]...)
	}
}

func neoReplayEventMessageID(payload map[string]any) string {
	switch stringValue(payload["type"]) {
	case "delta":
		return stringValue(payload["messageId"])
	case "message_added", "message_updated":
		return stringValue(mapValue(payload["message"])["messageId"])
	}
	return ""
}

func neoReplayEventRepresentedByMessages(payload map[string]any, messageIDs, toolCallIDs map[string]bool) bool {
	if messageID := neoReplayEventMessageID(payload); messageID != "" && messageIDs[messageID] {
		return true
	}
	return stringValue(payload["type"]) == "tool_progress" && toolCallIDs[stringValue(payload["toolCallId"])]
}

func cloneNeoProtocolPayload(payload map[string]any) map[string]any {
	out := cloneMap(payload)
	if message, ok := asMap(out["message"]); ok {
		cloned := cloneMap(message)
		if content := arrayValue(cloned["content"]); content != nil {
			cloned["content"] = cloneArray(content)
		}
		out["message"] = cloned
	}
	if errorPayload, ok := asMap(out["error"]); ok {
		out["error"] = cloneMap(errorPayload)
	}
	if blocks := arrayValue(out["blocks"]); blocks != nil {
		out["blocks"] = cloneArray(blocks)
	}
	if usage := mapValue(out["usage"]); len(usage) > 0 {
		out["usage"] = cloneMap(usage)
	}
	return out
}

func (a *neoActor) agentModeLocked() string {
	if mode := stringValue(a.settings["agentMode"]); mode != "" {
		return mode
	}
	for _, message := range a.messages {
		if message.Role == "user" && message.AgentMode != "" {
			return message.AgentMode
		}
	}
	if a.currentAgentMode != "" {
		return a.currentAgentMode
	}
	return "smart"
}

func (a *neoActor) initialQueuedUserModeLocked() (string, string) {
	if a.mainThreadID != "" || a.hasUserTurnLocked() || len(a.queue) == 0 {
		return "", ""
	}
	next := a.queue[a.nextQueuedMessageIndexLocked()]
	mode := next.AgentMode
	if !validNeoClientAgentMode(mode) {
		return "", ""
	}
	effort := next.ReasoningEffort
	if !neoReasoningEffortAllowedForMode(mode, effort) {
		effort = defaultNeoReasoningEffort(mode)
	}
	return mode, effort
}

func (a *neoActor) reasoningEffortLocked() string {
	return a.reasoningEffortForModeLocked(a.agentModeLocked())
}

func (a *neoActor) reasoningEffortForModeLocked(agentMode string) string {
	if !neoModeSupportsReasoningEffort(agentMode) {
		return ""
	}
	if effort := stringValue(a.settings["reasoning.effort"]); neoReasoningEffortAllowedForMode(agentMode, effort) {
		return effort
	}
	if strings.EqualFold(a.currentAgentMode, agentMode) && neoReasoningEffortAllowedForMode(agentMode, a.currentReasoningEffort) {
		return a.currentReasoningEffort
	}
	for i := len(a.messages) - 1; i >= 0; i-- {
		message := a.messages[i]
		if message.Role != "user" || message.ReasoningEffort == "" {
			continue
		}
		if message.AgentMode != "" && !strings.EqualFold(message.AgentMode, agentMode) {
			continue
		}
		if neoReasoningEffortAllowedForMode(agentMode, message.ReasoningEffort) {
			return message.ReasoningEffort
		}
	}
	return defaultNeoReasoningEffort(agentMode)
}

func defaultNeoReasoningEffort(agentMode string) string {
	switch strings.ToLower(strings.TrimSpace(agentMode)) {
	case "low":
		return "medium"
	case "medium":
		return "medium"
	case "high":
		return "xhigh"
	case "ultra":
		return "high"
	case "smart":
		return "high"
	case "rush":
		return "none"
	case "deep":
		return "medium"
	case "review":
		return "medium"
	case "agg-man":
		return "none"
	case "nostromo":
		return "low"
	default:
		return ""
	}
}

func normalizeNeoReasoningEffortForMode(agentMode, effort string) string {
	if neoReasoningEffortAllowedForMode(agentMode, effort) {
		return strings.ToLower(strings.TrimSpace(effort))
	}
	return defaultNeoReasoningEffort(agentMode)
}

func neoModeSupportsReasoningEffort(agentMode string) bool {
	switch strings.ToLower(strings.TrimSpace(agentMode)) {
	case "low", "medium", "high", "ultra", "smart", "rush", "deep", "review", "agg-man", "nostromo":
		return true
	default:
		return false
	}
}

func neoReasoningEffortAllowedForMode(agentMode, effort string) bool {
	effort = strings.ToLower(strings.TrimSpace(effort))
	if effort == "" {
		return false
	}
	switch strings.ToLower(strings.TrimSpace(agentMode)) {
	case "low":
		return effort == "medium"
	case "medium":
		return effort == "medium"
	case "high":
		return effort == "xhigh"
	case "ultra":
		return effort == "high"
	case "smart":
		return effort == "high" || effort == "xhigh" || effort == "max"
	case "rush", "agg-man":
		return effort == "none"
	case "deep":
		return effort == "low" || effort == "medium" || effort == "xhigh"
	case "review":
		// the binary's review mode exposes no effort control; the amp review
		// CLI still sends --thinking low|high as the thread effort.
		return effort == "low" || effort == "medium" || effort == "high"
	case "nostromo":
		return effort == "low"
	default:
		return false
	}
}

func toolSet(names ...string) map[string]bool {
	out := make(map[string]bool, len(names))
	for _, name := range names {
		out[name] = true
	}
	return out
}

func toolList(names ...string) []string {
	return names
}

func orderedToolSets(lists map[string][]string) map[string]map[string]bool {
	out := make(map[string]map[string]bool, len(lists))
	for mode, names := range lists {
		out[mode] = toolSet(names...)
	}
	return out
}

func neoToolAllowedForMode(agentMode, name string) bool {
	agentMode = strings.ToLower(strings.TrimSpace(agentMode))
	if agentMode == "" {
		agentMode = "smart"
	}
	allowlist := neoModeToolAllowlist[agentMode]
	if len(allowlist) == 0 {
		allowlist = neoModeToolAllowlist["smart"]
	}
	if !neoKnownModeTools[name] {
		return false
	}
	return allowlist[name]
}

func neoDeferredToolAllowedForMode(agentMode, name string) bool {
	agentMode = strings.ToLower(strings.TrimSpace(agentMode))
	if agentMode == "" {
		agentMode = "smart"
	}
	allowlist := neoModeDeferredToolAllowlist[agentMode]
	if len(allowlist) == 0 {
		return false
	}
	return allowlist[name]
}

func neoToolIncludedForMode(agentMode string, tool neoToolSpec, settings map[string]any) bool {
	if deferred, _ := tool.Meta["deferred"].(bool); deferred {
		return neoDeferredToolAllowedForMode(agentMode, tool.Name) && neoToolAllowedBySettings(tool, settings)
	}
	if neoToolHasExternalSource(tool) {
		return neoToolAllowedBySettings(tool, settings)
	}
	return neoToolAllowedForMode(agentMode, tool.Name) && neoToolAllowedBySettings(tool, settings)
}

func neoToolHasExternalSource(tool neoToolSpec) bool {
	source := mapValue(tool.Meta["source"])
	if len(source) == 0 {
		return false
	}
	return stringValue(source["mcp"]) != "" || stringValue(source["toolbox"]) != "" || stringValue(source["plugin"]) != ""
}

func neoApplyScaffoldToolCustomization(tools []neoToolSpec, settings map[string]any) ([]neoToolSpec, error) {
	custom := neoLoadScaffoldCustomization(settings, false, nil, nil)
	if custom == nil {
		return tools, nil
	}
	out := append([]neoToolSpec(nil), tools...)
	if custom.EnableToolSpecs != nil {
		enabled := make([]neoToolSpec, 0, len(*custom.EnableToolSpecs))
		for _, tool := range out {
			if neoScaffoldHasToolSpec(*custom.EnableToolSpecs, tool.Name) {
				enabled = append(enabled, tool)
			}
		}
		out = enabled
	}
	if len(custom.DisableTools) > 0 {
		filtered := out[:0]
		for _, tool := range out {
			if !neoScaffoldToolNameInList(custom.DisableTools, tool.Name) {
				filtered = append(filtered, tool)
			}
		}
		out = filtered
	}
	if custom.EnableToolSpecs != nil && len(*custom.EnableToolSpecs) > 0 {
		for _, override := range *custom.EnableToolSpecs {
			index := neoScaffoldToolIndex(out, override.Name)
			if index < 0 {
				return nil, fmt.Errorf("Tool spec %s not found in original list", override.Name)
			}
			if override.Description != "" {
				out[index].Description = override.Description
			}
			if override.InputSchema != nil {
				out[index].InputSchema = cloneMap(override.InputSchema)
			}
		}
	}
	return out, nil
}

func neoScaffoldHasToolSpec(specs []neoScaffoldToolSpec, name string) bool {
	return neoScaffoldToolIndexBySpec(specs, name) >= 0
}

func neoScaffoldToolIndexBySpec(specs []neoScaffoldToolSpec, name string) int {
	for i, spec := range specs {
		if spec.Name == name {
			return i
		}
	}
	return -1
}

func neoScaffoldToolIndex(tools []neoToolSpec, name string) int {
	for i, tool := range tools {
		if tool.Name == name {
			return i
		}
	}
	return -1
}

func neoScaffoldToolNameInList(names []string, name string) bool {
	for _, candidate := range names {
		if candidate == name {
			return true
		}
	}
	return false
}

func neoToolAllowedBySettings(tool neoToolSpec, settings map[string]any) bool {
	enable := neoToolSettingPatterns(settings, "tools.enable")
	if len(enable) > 0 && !neoToolMatchesAnyPattern(tool, enable) {
		return false
	}
	disable := neoToolSettingPatterns(settings, "tools.disable")
	if len(disable) > 0 && neoToolMatchesAnyPattern(tool, disable) {
		return false
	}
	return true
}

func neoToolSettingPatterns(settings map[string]any, key string) []string {
	if len(settings) == 0 {
		return neoDefaultToolSettingPatterns(key)
	}
	raw, ok := settings[key]
	if !ok {
		return neoDefaultToolSettingPatterns(key)
	}
	switch value := raw.(type) {
	case []string:
		out := make([]string, 0, len(value))
		for _, item := range value {
			if item != "" {
				out = append(out, item)
			}
		}
		return out
	case []any:
		out := make([]string, 0, len(value))
		for _, item := range value {
			text, ok := item.(string)
			if !ok {
				return nil
			}
			if text != "" {
				out = append(out, text)
			}
		}
		return out
	default:
		return nil
	}
}

func neoDefaultToolSettingPatterns(key string) []string {
	switch key {
	case "tools.disable":
		return []string{"browser_navigate", "builtin:edit_file"}
	default:
		return nil
	}
}

func neoToolMatchesAnyPattern(tool neoToolSpec, patterns []string) bool {
	candidates := neoToolPatternCandidates(tool)
	for _, pattern := range patterns {
		pattern = strings.TrimSpace(pattern)
		if pattern == "" {
			continue
		}
		for _, candidate := range candidates {
			if neoToolPatternMatches(candidate, pattern) {
				return true
			}
		}
	}
	return false
}

func neoToolPatternCandidates(tool neoToolSpec) []string {
	seen := map[string]bool{}
	out := []string{}
	add := func(value string) {
		value = strings.TrimSpace(value)
		if value == "" || seen[value] {
			return
		}
		seen[value] = true
		out = append(out, value)
	}
	add(tool.Name)
	source := tool.Meta["source"]
	if stringValue(source) == "builtin" {
		add("builtin:" + tool.Name)
	}
	if sourceMap := mapValue(source); len(sourceMap) > 0 {
		if server := stringValue(sourceMap["mcp"]); server != "" {
			normalized := neoNormalizeMCPServerName(server)
			if parsed, ok := neoParseMCPToolName(tool.Name); ok {
				add(parsed.tool)
				if parsed.server == normalized {
					add("mcp__" + server + "__" + parsed.tool)
				}
			}
		}
		if stringValue(sourceMap["toolbox"]) != "" {
			add("toolbox:" + tool.Name)
		}
	}
	if parsed, ok := neoParseMCPToolName(tool.Name); ok {
		add(parsed.tool)
		add("mcp__" + parsed.server + "__" + parsed.tool)
	}
	return out
}

func neoNormalizeMCPServerName(name string) string {
	return neoMCPServerPattern.ReplaceAllString(name, "_")
}

type neoMCPToolName struct {
	server string
	tool   string
}

func neoParseMCPToolName(name string) (neoMCPToolName, bool) {
	parts := strings.SplitN(name, "__", 3)
	if len(parts) != 3 || parts[0] != "mcp" || parts[1] == "" || parts[2] == "" {
		return neoMCPToolName{}, false
	}
	return neoMCPToolName{server: parts[1], tool: parts[2]}, true
}

func neoToolPatternMatches(candidate, pattern string) bool {
	if pattern == "*" || candidate == pattern {
		return true
	}
	if strings.Contains(pattern, "{") {
		for _, expanded := range neoExpandBracePattern(pattern, 128) {
			if expanded != pattern && neoToolPatternMatches(candidate, expanded) {
				return true
			}
		}
	}
	if strings.ContainsAny(pattern, "*?[") {
		if ok, err := filepath.Match(pattern, candidate); err == nil && ok {
			return true
		}
	}
	return false
}

func neoExpandBracePattern(pattern string, limit int) []string {
	if limit <= 0 {
		return []string{pattern}
	}
	start := strings.Index(pattern, "{")
	if start < 0 {
		return []string{pattern}
	}
	depth := 0
	end := -1
	for i := start; i < len(pattern); i++ {
		switch pattern[i] {
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				end = i
				break
			}
		}
	}
	if end < 0 {
		return []string{pattern}
	}
	alts := neoSplitBraceAlternatives(pattern[start+1 : end])
	if len(alts) == 0 {
		return []string{pattern}
	}
	out := make([]string, 0, len(alts))
	for _, alt := range alts {
		for _, expanded := range neoExpandBracePattern(pattern[:start]+alt+pattern[end+1:], limit-len(out)) {
			out = append(out, expanded)
			if len(out) >= limit {
				return out
			}
		}
	}
	return out
}

func neoSplitBraceAlternatives(value string) []string {
	depth := 0
	start := 0
	out := []string{}
	for i := 0; i < len(value); i++ {
		switch value[i] {
		case '{':
			depth++
		case '}':
			if depth > 0 {
				depth--
			}
		case ',':
			if depth == 0 {
				out = append(out, value[start:i])
				start = i + 1
			}
		}
	}
	out = append(out, value[start:])
	return out
}

func (a *neoActor) toolNamesLocked(agentMode string) []string {
	tools := a.toolsForModeLocked(agentMode, a.history)
	names := make([]string, 0, len(tools))
	for _, tool := range tools {
		names = append(names, tool.Name)
	}
	sort.Strings(names)
	return names
}

func (a *neoActor) pendingToolIDsLocked() []string {
	ids := make([]string, 0, len(a.pendingTools))
	for id := range a.pendingTools {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

func (a *neoActor) approvalToolIDsLocked() []string {
	ids := make([]string, 0, len(a.approvalQueue))
	seen := map[string]bool{}
	for _, approval := range a.approvalQueue {
		id := neoApprovalKey(approval)
		if id == "" || seen[id] {
			continue
		}
		seen[id] = true
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

type neoSocket struct {
	mu               sync.Mutex
	conn             *websocket.Conn
	snapshotSent     bool
	jsonRPC          bool
	rivetAction      bool
	rivetBare        bool
	rivetConnection  string
	localExtensions  bool
	webLocalObserver bool
	executor         bool
	executorID       string
	clientAPIKey     string
	runnerID         string
}

func (s *neoSocket) clientKey() string {
	if s == nil {
		return ""
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.clientAPIKey
}

func (s *neoSocket) runnerKey() string {
	if s == nil {
		return ""
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return strings.TrimSpace(s.runnerID)
}

func (s *neoSocket) markSnapshotSent() {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.snapshotSent = true
	s.mu.Unlock()
}

func (s *neoSocket) markExecutor(executorID ...string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.executor = true
	if len(executorID) > 0 && strings.TrimSpace(executorID[0]) != "" {
		s.executorID = strings.TrimSpace(executorID[0])
	}
	s.mu.Unlock()
}

func (s *neoSocket) clearExecutor() {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.executor = false
	s.executorID = ""
	s.mu.Unlock()
}

func (s *neoSocket) isExecutor() bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.executor
}

func (s *neoSocket) executorKey() string {
	if s == nil {
		return ""
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.executorID
}

func (s *neoSocket) hasSnapshotSent() bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.snapshotSent
}

func (s *neoSocket) setJSONRPC(enabled bool) {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.jsonRPC = enabled
	s.mu.Unlock()
}

func (s *neoSocket) setRivetAction(enabled bool) {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.rivetAction = enabled
	s.mu.Unlock()
}

func (s *neoSocket) setRivetBare(enabled bool) {
	if s == nil {
		return
	}
	s.mu.Lock()
	s.rivetBare = enabled
	s.mu.Unlock()
}

func (s *neoSocket) isJSONRPC() bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.jsonRPC
}

func (s *neoSocket) isRivetAction() bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.rivetAction
}

func (s *neoSocket) isRivetBare() bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.rivetBare
}

func (s *neoSocket) allowsLocalExtensions() bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.localExtensions
}

func (s *neoSocket) isWebLocalObserver() bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.webLocalObserver
}

func neoWebLocalObserverPayload(payload any) (any, bool) {
	if stringValue(mapValue(payload)["type"]) == "executor_connected" {
		return nil, false
	}
	return payload, true
}

func (s *neoSocket) send(payload any) {
	cleaned := normalizeNeoOutboundJSON(payload)
	if s.isWebLocalObserver() {
		var ok bool
		cleaned, ok = neoWebLocalObserverPayload(cleaned)
		if !ok {
			log.Debugf("amp neo local runtime WS skip web local observer payload %s", neoProtocolSummary(payload))
			return
		}
	}
	if !s.allowsLocalExtensions() && neoOutboundLocalExtensionOnly(cleaned) {
		log.Debugf("amp neo local runtime WS skip local extension %s", neoProtocolSummary(cleaned))
		return
	}
	if s.isRivetAction() {
		if frame, ok := neoRivetEventFrame(cleaned, s.isWebLocalObserver()); ok {
			if s.isRivetBare() {
				event := mapValue(mapValue(frame["body"])["val"])
				data, err := neoRivetEncodeEventFrame(stringValue(event["name"]), event["args"])
				if err != nil {
					return
				}
				log.Debugf("amp neo local runtime WS send %s", neoProtocolSummary(cleaned))
				s.sendBinary(data)
				return
			}
			data, err := json.Marshal(frame)
			if err != nil {
				return
			}
			log.Debugf("amp neo local runtime WS send %s", neoProtocolSummary(cleaned))
			s.sendText(string(data))
		}
		return
	}
	if s.isJSONRPC() {
		if frame, ok := neoJSONRPCNotification(cleaned); ok {
			data, err := json.Marshal(frame)
			if err != nil {
				return
			}
			log.Debugf("amp neo local runtime WS send %s", neoProtocolSummary(cleaned))
			s.sendText(string(data))
			return
		}
	}
	data, err := json.Marshal(cleaned)
	if err != nil {
		return
	}
	log.Debugf("amp neo local runtime WS send %s", neoProtocolSummary(cleaned))
	s.sendText(string(data))
}

func (s *neoSocket) sendRivetInit(actorID string) {
	if s == nil || !s.isRivetAction() {
		return
	}
	s.mu.Lock()
	connectionID := s.rivetConnection
	s.mu.Unlock()
	if connectionID == "" {
		connectionID = "conn-" + randomBase62(22)
	}
	if s.isRivetBare() {
		s.sendBinary(neoRivetEncodeInitFrame(actorID, connectionID))
		return
	}
	frame := map[string]any{
		"body": map[string]any{
			"tag": "Init",
			"val": map[string]any{
				"actorId":      actorID,
				"connectionId": connectionID,
			},
		},
	}
	data, err := json.Marshal(frame)
	if err != nil {
		return
	}
	s.sendText(string(data))
}

func (s *neoSocket) sendRivetActionResponse(id any, result any) {
	if s == nil || id == nil || !s.isRivetAction() {
		return
	}
	if s.isRivetBare() {
		requestID, ok := neoRivetRequestIDUint64(id)
		if !ok {
			return
		}
		data, err := neoRivetEncodeActionResponseFrame(requestID, result)
		if err != nil {
			return
		}
		s.sendBinary(data)
		return
	}
	frame := map[string]any{
		"body": map[string]any{
			"tag": "ActionResponse",
			"val": map[string]any{
				"id":     id,
				"output": result,
			},
		},
	}
	data, err := json.Marshal(frame)
	if err != nil {
		return
	}
	s.sendText(string(data))
}

func neoRivetEventFrame(payload any, webLocalObserver bool) (map[string]any, bool) {
	msg := mapValue(payload)
	name := stringValue(msg["type"])
	if name == "" {
		return nil, false
	}
	if !webLocalObserver && name != "threadStatusUpdated" {
		return nil, false
	}
	args := cloneMap(msg)
	if !webLocalObserver {
		delete(args, "type")
		return map[string]any{
			"body": map[string]any{
				"tag": "Event",
				"val": map[string]any{
					"name": name,
					"args": []any{args},
				},
			},
		}, true
	}
	return map[string]any{
		"body": map[string]any{
			"tag": "Event",
			"val": map[string]any{
				"name": name,
				"args": []any{args},
			},
		},
	}, true
}

func neoRivetRequestIDUint64(value any) (uint64, bool) {
	switch typed := value.(type) {
	case uint64:
		return typed, true
	case uint:
		return uint64(typed), true
	case uint32:
		return uint64(typed), true
	case int:
		if typed < 0 {
			return 0, false
		}
		return uint64(typed), true
	case int64:
		if typed < 0 {
			return 0, false
		}
		return uint64(typed), true
	case float64:
		if typed < 0 || typed != float64(uint64(typed)) {
			return 0, false
		}
		return uint64(typed), true
	case json.Number:
		parsed, err := strconv.ParseUint(string(typed), 10, 64)
		return parsed, err == nil
	case string:
		parsed, err := strconv.ParseUint(typed, 10, 64)
		return parsed, err == nil
	default:
		return 0, false
	}
}

func neoLocalRuntimeExtensionsRequested(r *http.Request) bool {
	if r == nil || r.URL == nil {
		return false
	}
	return strings.EqualFold(strings.TrimSpace(r.URL.Query().Get("cliproxy-client")), "neo-remote-ui")
}

func neoOutboundLocalExtensionOnly(payload any) bool {
	msg := mapValue(payload)
	switch stringValue(msg["type"]) {
	case "artifact_deleted",
		"artifact_upserted",
		"artifacts_snapshot",
		"clearPendingNavigation",
		"draft",
		"main-thread",
		"max-tokens",
		"setPendingNavigation":
		return true
	default:
		return false
	}
}

func neoInboundExecutorMessage(msgType string) bool {
	return msgType == "executor_connected" ||
		msgType == "executor_connect" ||
		msgType == "executor_disconnected" ||
		strings.HasPrefix(msgType, "executor_")
}

func neoInboundWebLocalObserverBlockedMessage(msgType string) bool {
	return neoInboundExecutorMessage(msgType) || msgType == "client_spawn_executor"
}

func (s *neoSocket) sendJSONRPCResponse(id any, result any) {
	if s == nil || id == nil || !s.isJSONRPC() {
		return
	}
	frame := map[string]any{
		"jsonrpc": "2.0",
		"id":      id,
		"result":  result,
	}
	data, err := json.Marshal(frame)
	if err != nil {
		return
	}
	s.sendText(string(data))
}

func neoJSONRPCNotification(payload any) (map[string]any, bool) {
	msg, ok := payload.(map[string]any)
	if !ok {
		return nil, false
	}
	method := stringValue(msg["type"])
	if method == "" {
		return nil, false
	}
	params := cloneMap(msg)
	delete(params, "type")
	return map[string]any{
		"jsonrpc": "2.0",
		"method":  method,
		"params":  params,
	}, true
}

func (s *neoSocket) sendText(text string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.conn.WriteMessage(websocket.TextMessage, []byte(text)); err != nil {
		log.Debugf("amp neo local runtime WS send failed: %v", err)
	}
}

func (s *neoSocket) sendBinary(data []byte) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.conn.WriteMessage(websocket.BinaryMessage, data); err != nil {
		log.Debugf("amp neo local runtime WS send failed: %v", err)
	}
}

func (s *neoSocket) close(code int, reason string) {
	if s == nil || s.conn == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	message := websocket.FormatCloseMessage(code, reason)
	_ = s.conn.WriteControl(websocket.CloseMessage, message, time.Now().Add(time.Second))
	_ = s.conn.Close()
}

func (s *neoSocket) closeTransport() {
	if s == nil || s.conn == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	_ = s.conn.Close()
}

func pruneNilJSON(value any) any {
	switch typed := value.(type) {
	case map[string]any:
		out := make(map[string]any, len(typed))
		for key, item := range typed {
			if item == nil {
				continue
			}
			out[key] = pruneNilJSON(item)
		}
		return out
	case []any:
		out := make([]any, 0, len(typed))
		for _, item := range typed {
			if item == nil {
				continue
			}
			out = append(out, pruneNilJSON(item))
		}
		return out
	default:
		return value
	}
}

// neoExplicitNullSentinel marks values that must be serialized as JSON `null`
// rather than elided (e.g. activeError clearance, parentToolCallId reset).
type neoExplicitNullSentinel struct{}

var neoExplicitNull any = neoExplicitNullSentinel{}

func (neoExplicitNullSentinel) MarshalJSON() ([]byte, error) {
	return []byte("null"), nil
}

// normalizeNeoOutboundJSON drops nil values but preserves explicit nulls
// produced by the runtime. Use neoExplicitNull when "null" carries semantic
// meaning to the client (clear active error, no parent, reset value).
func normalizeNeoOutboundJSON(value any) any {
	normalized, _ := normalizeNeoOutboundJSONValue(value)
	return normalized
}

func normalizeNeoOutboundJSONValue(value any) (any, bool) {
	switch typed := value.(type) {
	case neoExplicitNullSentinel:
		return typed, false
	case map[string]any:
		if typed == nil {
			return map[string]any{}, true
		}
		var out map[string]any
		for key, item := range typed {
			if item == nil {
				if out == nil {
					out = cloneMap(typed)
				}
				delete(out, key)
				continue
			}
			normalized, changed := normalizeNeoOutboundJSONValue(item)
			if changed {
				if out == nil {
					out = cloneMap(typed)
				}
				out[key] = normalized
			}
		}
		if out != nil {
			return out, true
		}
		return typed, false
	case []any:
		if typed == nil {
			return []any{}, true
		}
		var out []any
		for i, item := range typed {
			if item == nil {
				if out == nil {
					out = make([]any, 0, len(typed)-1)
					out = append(out, typed[:i]...)
				}
				continue
			}
			normalized, changed := normalizeNeoOutboundJSONValue(item)
			if changed && out == nil {
				out = make([]any, 0, len(typed))
				out = append(out, typed[:i]...)
			}
			if out != nil {
				out = append(out, normalized)
			}
		}
		if out != nil {
			return out, true
		}
		return typed, false
	default:
		return value, false
	}
}

func neoProtocolSummary(payload any) string {
	m, ok := payload.(map[string]any)
	if !ok {
		return fmt.Sprintf("payload=%T", payload)
	}
	parts := make([]string, 0, 10)
	for _, key := range []string{"type", "state", "role", "messageId", "seq", "agentMode", "reasoningEffort", "queuedMessageId", "toolCallId", "parentToolCallId", "parentToolUseId"} {
		if value, ok := m[key]; ok {
			parts = append(parts, fmt.Sprintf("%s=%v", key, value))
		}
	}
	if blocks, ok := m["blocks"].([]any); ok {
		parts = append(parts, fmt.Sprintf("blocks=%d", len(blocks)))
	}
	if message, ok := m["message"].(map[string]any); ok {
		if role := stringValue(message["role"]); role != "" {
			parts = append(parts, "messageRole="+role)
		}
		if id := stringValue(message["messageId"]); id != "" {
			parts = append(parts, "messageId="+id)
		}
		if state := stringValue(mapValue(message["state"])["type"]); state != "" {
			parts = append(parts, "messageState="+state)
		}
		if content, ok := message["content"].([]any); ok {
			parts = append(parts, fmt.Sprintf("messageBlocks=%d", len(content)))
		}
	}
	if len(parts) == 0 {
		return fmt.Sprintf("payload=%T", payload)
	}
	return strings.Join(parts, " ")
}

